//! Runs a Java mod's entrypoint on an embedded JVM, against a façade jar
//! generated by `horizon-port-pack facade` (`docs/java-mod-compat.md`,
//! phase 1's first slice).
//!
//! ```sh
//! horizon-jvm [--entry dev.example.MyMod] [--mixin-config demo.mixins.json] \
//!     [--fabric-development] --stubs facade.jar --loader fabric-loader.jar \
//!     --libs ~/.minecraft/libraries mod.jar [more jars...]
//! ```
//!
//! The supplied jars also go to Fabric Loader through its documented
//! `fabric.addMods` developer property, so the loader itself registers their
//! mixin configs and entrypoints instead of only this runner's own scans.
//!
//! The façade's methods throw `UnsupportedOperationException` naming
//! themselves, so the first one the mod reaches is the next thing the game
//! must implement. That is this binary's job today: prove the attach path and
//! get the exact failure.
use jni::{
    InitArgsBuilder, JNIEnv, JNIVersion, JavaVM,
    objects::{JClass, JObject, JObjectArray, JValue, JValueOwned},
};
use std::{
    fs::{self, File},
    path::{Path, PathBuf},
    process::{Command, ExitCode},
    time::{SystemTime, UNIX_EPOCH},
};

/// Owns extracted Fabric nested jars for the duration of the JVM.
struct NestedJars {
    root: PathBuf,
}

impl NestedJars {
    fn new() -> Result<Self, String> {
        let stamp = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .map_err(|e| format!("clock: {e}"))?
            .as_nanos();
        let root = std::env::temp_dir().join(format!("horizon-jvm-{}-{stamp}", std::process::id()));
        fs::create_dir_all(&root).map_err(|e| format!("{}: {e}", root.display()))?;
        Ok(Self { root })
    }
}

impl Drop for NestedJars {
    fn drop(&mut self) {
        let _ = fs::remove_dir_all(&self.root);
    }
}

const LOADER_BRIDGE_SOURCE: &str = r#"
import java.io.*;
import java.lang.reflect.*;
import java.nio.file.*;
import java.util.*;
import java.util.stream.Collectors;

/** Small reflection-only bridge used by the embedded Fabric probe. */
@SuppressWarnings({"unchecked", "rawtypes"})
public final class HorizonLoaderBridge {
  private HorizonLoaderBridge() {}

  public static void seed(String id, String version) throws Exception {
    Class<?> impl = Class.forName("net.fabricmc.loader.impl.FabricLoaderImpl");
    Object loader = impl.getField("INSTANCE").get(null);
    Class<?> modContainer = Class.forName("net.fabricmc.loader.api.ModContainer");
    Class<?> metadata = Class.forName("net.fabricmc.loader.api.metadata.ModMetadata");
    Class<?> ver = Class.forName("net.fabricmc.loader.api.Version");
    Object versionObject = Proxy.newProxyInstance(ver.getClassLoader(), new Class<?>[]{ver}, (p, m, a) -> {
      if (m.getName().equals("getFriendlyString") || m.getName().equals("toString")) return version;
      if (m.getName().equals("compareTo")) return 0;
      if (m.getReturnType() == boolean.class) return false;
      if (m.getReturnType().isPrimitive()) return 0;
      return null;
    });
    Object metadataObject = Proxy.newProxyInstance(metadata.getClassLoader(), new Class<?>[]{metadata}, (p, m, a) -> {
      switch (m.getName()) {
        case "getId": case "getName": return id;
        case "getVersion": return versionObject;
        case "getType": return "normal";
        case "getDescription": return "";
        case "getEnvironment":
          return Enum.valueOf((Class) Class.forName("net.fabricmc.loader.api.metadata.ModEnvironment"), "UNIVERSAL");
        case "getProvides": case "getLicense": case "getAuthors": case "getContributors":
        case "getDependencies": case "getDepends": case "getRecommends": case "getSuggests":
        case "getConflicts": case "getBreaks": return Collections.emptyList();
        case "getCustomValues": return Collections.emptyMap();
        case "containsCustomValue": case "containsCustomElement": return false;
        case "getIconPath": return Optional.empty();
        case "getCustomValue": case "getContact": return null;
        default:
          if (m.getReturnType() == boolean.class) return false;
          if (m.getReturnType().isPrimitive()) return 0;
          return null;
      }
    });
    Object container = Proxy.newProxyInstance(modContainer.getClassLoader(), new Class<?>[]{modContainer}, (p, m, a) -> {
      switch (m.getName()) {
        case "getMetadata": return metadataObject;
        case "getRootPaths": case "getContainedMods": return Collections.emptyList();
        case "getContainingMod": return Optional.empty();
        case "getOrigin": case "getRootPath": case "getPath": return null;
        default:
          if (m.getReturnType() == boolean.class) return false;
          if (m.getReturnType().isPrimitive()) return 0;
          return null;
      }
    });
    Field mapField = impl.getDeclaredField("modMap");
    mapField.setAccessible(true);
    Object previous = ((Map) mapField.get(loader)).putIfAbsent(id, container);
    if (previous != null) return;
    Field modsField = impl.getDeclaredField("mods");
    modsField.setAccessible(true);
    ((List) modsField.get(loader)).add(container);
  }

  /** Drive the real Fabric loader: launcher, game provider, load and freeze. */
  public static int bootstrap() throws Exception {
    Class<?> base = Class.forName("net.fabricmc.loader.impl.launch.FabricLauncherBase");
    Class<?> launcherIface = Class.forName("net.fabricmc.loader.impl.launch.FabricLauncher");
    Object launcher = Proxy.newProxyInstance(launcherIface.getClassLoader(), new Class<?>[]{launcherIface}, (p, m, a) -> {
      switch (m.getName()) {
        case "getClassPath":
          return Arrays.stream(System.getProperty("java.class.path").split(File.pathSeparator))
              .map(Paths::get).collect(Collectors.toList());
        case "getTargetClassLoader": return ClassLoader.getSystemClassLoader();
        case "getResourceAsStream": return ClassLoader.getSystemResourceAsStream((String) a[0]);
        case "getClassByteArray": {
          String name = (String) a[0];
          try (InputStream in = ClassLoader.getSystemResourceAsStream(name.replace('.', '/') + ".class")) {
            if (in == null) throw new IOException(name);
            return in.readAllBytes();
          }
        }
        case "getEnvironmentType":
          return Enum.valueOf((Class) Class.forName("net.fabricmc.api.EnvType"), "SERVER");
        case "isDevelopment": return true;
        case "getEntrypoint": return "net.fabricmc.loader.impl.launch.knot.KnotClient";
        case "getManifest": return null;
        case "getMappingConfiguration": return mappingConfiguration();
        case "isClassLoaded": return false;
        case "loadIntoTarget": throw new ClassNotFoundException((String) a[0]);
        default: return defaultValue(m.getReturnType());
      }
    });
    base.getMethod("setLauncher", launcherIface).invoke(null, launcher);
    Field properties = base.getDeclaredField("properties");
    properties.setAccessible(true);
    properties.set(null, new HashMap<String, Object>());
    Class<?> providerIface = Class.forName("net.fabricmc.loader.impl.game.GameProvider");
    Object provider = Proxy.newProxyInstance(providerIface.getClassLoader(), new Class<?>[]{providerIface}, (p, m, a) -> {
      switch (m.getName()) {
        case "getGameId": return "minecraft";
        case "getGameName": return "Horizon";
        case "getRawGameVersion": case "getNormalizedGameVersion": return "26.3";
        case "getBuiltinMods": return Collections.emptyList();
        case "getEntrypoint": return "net.fabricmc.loader.impl.launch.knot.KnotClient";
        case "getLaunchDirectory": return Paths.get(".");
        case "requiresUrlClassLoader": case "isEnabled": case "locateGame":
        case "hasAwtSupport": case "canOpenErrorGui": return true;
        case "getBuiltinTransforms": return Collections.emptySet();
        case "initialize": case "unlockClassPath": case "launch": return null;
        case "getEntrypointTransformer": return null;
        case "getArguments":
          return Class.forName("net.fabricmc.loader.impl.util.Arguments").getConstructor().newInstance();
        case "getLaunchArguments": return new String[0];
        default: return defaultValue(m.getReturnType());
      }
    });
    Class<?> impl = Class.forName("net.fabricmc.loader.impl.FabricLoaderImpl");
    Object loader = impl.getField("INSTANCE").get(null);
    impl.getMethod("setGameProvider", providerIface).invoke(loader, provider);
    impl.getMethod("load").invoke(loader);
    try {
      impl.getMethod("freeze").invoke(loader);
    } catch (Throwable ignored) {
      // A loader without freeze still exposes the containers.
    }
    return ((Collection<?>) impl.getMethod("getAllMods").invoke(loader)).size();
  }

  /** Invoke the loader's entrypoint containers for one lifecycle kind. */
  public static int run(String kind) throws Exception {
    Class<?> impl = Class.forName("net.fabricmc.loader.impl.FabricLoaderImpl");
    Object loader = impl.getField("INSTANCE").get(null);
    String iface = switch (kind) {
      case "client" -> "net.fabricmc.api.ClientModInitializer";
      case "server" -> "net.fabricmc.api.DedicatedServerModInitializer";
      default -> "net.fabricmc.api.ModInitializer";
    };
    String method = switch (kind) {
      case "client" -> "onInitializeClient";
      case "server" -> "onInitializeServer";
      default -> "onInitialize";
    };
    Class<?> type = Class.forName(iface);
    List<?> containers = (List<?>) impl
        .getMethod("getEntrypointContainers", String.class, Class.class)
        .invoke(loader, kind, type);
    for (Object container : containers) {
      Object entrypoint = container.getClass().getMethod("getEntrypoint").invoke(container);
      entrypoint.getClass().getMethod(method).invoke(entrypoint);
    }
    return containers.size();
  }

  private static Object mappingConfiguration() throws Exception {
    Class<?> type = Class.forName("net.fabricmc.loader.impl.launch.MappingConfiguration");
    Object config = type.getConstructor().newInstance();
    setField(type, config, "namespace", "named");
    setField(type, config, "gameId", "minecraft");
    setField(type, config, "gameVersion", "26.3");
    setField(type, config, "mappingName", "none");
    setField(type, config, "namespaces", Arrays.asList("official", "intermediary", "named"));
    setField(type, config, "initializedMetadata", true);
    setField(type, config, "initializedMappings", true);
    return config;
  }

  private static void setField(Class<?> type, Object target, String name, Object value) throws Exception {
    Field field = type.getDeclaredField(name);
    field.setAccessible(true);
    field.set(target, value);
  }

  private static Object defaultValue(Class<?> type) {
    if (!type.isPrimitive()) return null;
    if (type == boolean.class) return false;
    if (type == char.class) return (char) 0;
    if (type == byte.class) return (byte) 0;
    if (type == short.class) return (short) 0;
    if (type == int.class) return 0;
    if (type == long.class) return 0L;
    if (type == float.class) return 0f;
    return 0d;
  }
}
"#;

impl NestedJars {
    /// Compile the reflection-only Fabric metadata bridge without requiring
    /// loader classes on javac's classpath. The probe already requires a JDK
    /// for façade generation; if javac is unavailable, the rest of the probe
    /// still works and simply skips metadata seeding.
    fn compile_loader_bridge(&self) -> Option<PathBuf> {
        let source = self.root.join("HorizonLoaderBridge.java");
        let classes = self.root.join("loader-bridge");
        if fs::create_dir_all(&classes).is_err()
            || fs::write(&source, LOADER_BRIDGE_SOURCE).is_err()
        {
            return None;
        }
        let javac = std::env::var_os("JAVA_HOME")
            .map(PathBuf::from)
            .map(|home| home.join("bin").join("javac"))
            .unwrap_or_else(|| PathBuf::from("javac"));
        let Ok(status) = Command::new(javac)
            .arg("-Xlint:none")
            .arg("-nowarn")
            .arg("-d")
            .arg(&classes)
            .arg(&source)
            .status()
        else {
            return None;
        };
        status.success().then_some(classes)
    }
}

fn main() -> ExitCode {
    match run() {
        Ok(()) => ExitCode::SUCCESS,
        Err(e) => {
            eprintln!("error: {e}");
            ExitCode::FAILURE
        }
    }
}

/// The usage line, kept as data so a test can check the kinds it names.
const USAGE: &str = "usage: horizon-jvm [--entry <class>] [--entry-kind <main|client|server|preLaunch|neoforge|datagen>] [--real-loader] [--datagen-output <dir>] [--list-entrypoints] [--list-mixin-configs] [--mixin-config <path>]... [--fabric-development] [--stubs <jar>] [--loader <jar>] [--libs <dir>] <jar>...";

fn run() -> Result<(), String> {
    let mut args: Vec<String> = std::env::args().skip(1).collect();
    let list_entrypoints_only = args.iter().any(|arg| arg == "--list-entrypoints");
    args.retain(|arg| arg != "--list-entrypoints");
    let list_mixin_configs_only = args.iter().any(|arg| arg == "--list-mixin-configs");
    args.retain(|arg| arg != "--list-mixin-configs");
    // Fabric's loader-development mode is opt-in: a plain probe keeps the
    // production default, and the flag never reaches the jar list.
    let fabric_development = args.iter().any(|arg| arg == "--fabric-development");
    args.retain(|arg| arg != "--fabric-development");
    // Run the real Fabric or NeoForge loader instead of this probe's own scan.
    let real_loader = args.iter().any(|arg| arg == "--real-loader");
    args.retain(|arg| arg != "--real-loader");
    let mixin_config_args = take_all(&mut args, "--mixin-config");
    let entry = take(&mut args, "--entry");
    let entry_kind = take(&mut args, "--entry-kind").unwrap_or_else(|| "main".to_owned());
    let datagen_output = take(&mut args, "--datagen-output").map(PathBuf::from);
    let stubs = take(&mut args, "--stubs").map(PathBuf::from);
    let loader = take(&mut args, "--loader").map(PathBuf::from);
    let libs = take(&mut args, "--libs").map(PathBuf::from);
    let heap = take(&mut args, "--heap").unwrap_or_else(|| "-Xmx1g".to_owned());
    // Listing mixin configs is meaningful with only `--mixin-config` values,
    // so it runs before the classpath requirement.
    if list_mixin_configs_only {
        return list_mixin_configs(&args, &mixin_config_args);
    }
    if args.is_empty() {
        return Err(USAGE.to_owned());
    }
    if list_entrypoints_only {
        return list_entrypoints(&args);
    }
    // The FML path starts its own Java process with the loader's exact
    // classpath; an embedded JVM changes how FML's in-dev locator sees it.
    if real_loader && entry_kind == "neoforge" {
        let Some(libs) = libs.as_ref() else {
            return Err(
                "--real-loader --entry-kind neoforge needs --libs <installed server>/libraries"
                    .to_owned(),
            );
        };
        let mods: Vec<PathBuf> = args.iter().map(PathBuf::from).collect();
        return run_real_neoforge(libs, &mods);
    }
    let (entry_specs, pre_launch) = if real_loader {
        (Vec::new(), Vec::new())
    } else {
        match entry {
            Some(entry) => (vec![entry], Vec::new()),
            None => {
                let jar = Path::new(&args[0]);
                let metadata = metadata_path(jar)?;
                let entries = discover_entries(jar, &entry_kind)?;
                if entries.is_empty() {
                    let declared = declared_entrypoint_kinds(jar)?;
                    return Err(missing_entry_message(
                        &args[0],
                        &entry_kind,
                        metadata,
                        &declared,
                    ));
                }
                if metadata.is_none() {
                    report_neoforge_metadata(jar);
                }
                // Datagen is a build step of its own: loader-level `preLaunch`
                // callbacks do not run, so neither does any other lifecycle group.
                let pre_launch = if is_datagen_kind(&entry_kind) {
                    Vec::new()
                } else {
                    pre_launch_entries(jar, &entry_kind, metadata)?
                };
                (entries, pre_launch)
            }
        }
    };
    let datagen_mod = is_datagen_kind(&entry_kind)
        .then(|| fabric_metadata(Path::new(&args[0])))
        .flatten();

    let mut classpath: Vec<PathBuf> = Vec::new();
    if let Some(stubs) = stubs {
        classpath.push(stubs);
    }
    if let Some(loader) = loader {
        classpath.push(loader);
    }
    if let Some(libs) = libs {
        let (dependencies, skipped_game_jars) = jars(&libs)?;
        classpath.extend(dependencies);
        if skipped_game_jars != 0 {
            eprintln!(
                "horizon-jvm: skipped {skipped_game_jars} Minecraft runtime jar(s); the generated façade owns net.minecraft classes"
            );
        }
    }
    for arg in &args {
        classpath.push(PathBuf::from(arg));
    }
    if classpath.is_empty() {
        return Err("no classpath".to_owned());
    }
    let nested = expand_nested_jars(&mut classpath)?;
    if let Some(bridge) = nested.compile_loader_bridge() {
        classpath.insert(0, bridge);
    }
    // Datagen runs only the `fabric-datagen` callback: no client/server/main
    // initializer and no Mixin phase, so it branches before both are planned.
    if is_datagen_kind(&entry_kind) {
        return run_datagen(
            &classpath,
            &entry_specs,
            datagen_output.as_deref(),
            &heap,
            &nested,
            datagen_mod.as_ref(),
        );
    }
    // The selected environment filters the hand-off: a `client` config never
    // reaches a server run, and `main`/`preLaunch`/`neoforge` keep both sides.
    let mixin_environment = MixinEnvironment::selected(&entry_kind);
    let discovered = discover_mixin_configs(&classpath, &mixin_config_args);
    let mixin_skipped = skipped_mixin_configs(&discovered, mixin_environment);
    let mixin_configs = select_mixin_configs(discovered, mixin_environment);
    let mixin_report = report_mixin_configs(&mixin_configs);
    // Only configs a supplied jar (or an explicit `--mixin-config`) actually
    // carries reach the property; a path a jar declares but does not ship is
    // named in the report and left out so Mixin never chases it.
    let mixin_property = mixin_config_property(&mixin_configs);
    let mixin_registered = mixin_registered_count(mixin_property.as_deref());
    // Registration walks the same list the property carries, so the two
    // hand-offs can never name different configs or a different order.
    let mixin_names = mixin_config_names(mixin_property.as_deref());
    // Fabric's own mod discovery only sees jars the loader is told about. The
    // classpath above stays as it is; this property names the supplied jars as
    // mods, the documented developer hand-off for classpath mods.
    let supplied_jars: Vec<PathBuf> = args.iter().map(PathBuf::from).collect();
    let fabric_mods = fabric_add_mods(&supplied_jars);
    let skip_mc_provider = skip_mc_provider_requested(&fabric_environment_options());
    let paths = std::env::join_paths(&classpath).map_err(|e| e.to_string())?;
    let paths = paths.to_string_lossy().into_owned();

    let mut init = InitArgsBuilder::new()
        .version(JNIVersion::V8)
        .option(format!("-Djava.class.path={paths}"))
        .option(&heap)
        .option("-Djava.awt.headless=true");
    // Mixin reads its config list at launch time, so the property has to be in
    // the JVM options rather than set after `JavaVM::new`.
    for option in mixin_jvm_options(mixin_property.as_deref()) {
        init = init.option(option);
    }
    // Same for Fabric's developer properties: the loader reads them while it
    // discovers mods, which happens on the first loader class that loads.
    for option in fabric_jvm_options(fabric_mods.as_deref(), fabric_development, skip_mc_provider) {
        init = init.option(option);
    }
    let init = init.build().map_err(|e| format!("JVM options: {e}"))?;
    let jvm = JavaVM::new(init)
        .map_err(|e| format!("could not start a JVM ({e}); set JAVA_HOME to a JDK with libjvm"))?;
    let mut guard = jvm
        .attach_current_thread()
        .map_err(|e| format!("attach: {e}"))?;
    let env = &mut *guard;

    if real_loader {
        let bridge = match env.find_class("HorizonLoaderBridge") {
            Ok(class) => class,
            Err(_) => {
                let _ = env.exception_clear();
                return Err(
                    "real Fabric loader requested but HorizonLoaderBridge did not compile".into(),
                );
            }
        };
        let mods = env
            .call_static_method(&bridge, "bootstrap", "()I", &[])
            .and_then(|value| value.i())
            .map_err(|error| format!("Fabric loader bootstrap: {error}"))?;
        let kind = entry_kind.clone();
        let kind = env
            .new_string(kind)
            .map_err(|error| format!("loader kind: {error}"))?;
        let entrypoints = env
            .call_static_method(
                &bridge,
                "run",
                "(Ljava/lang/String;)I",
                &[JValue::Object(&JObject::from(kind))],
            )
            .and_then(|value| value.i())
            .map_err(|error| format!("Fabric loader entrypoints: {error}"))?;
        println!("real loader: {mods} mod(s), {entrypoints} {entry_kind} entrypoint(s)");
        return Ok(());
    }

    prepare_fabric_loader(env, &nested.root)?;
    seed_fabric_metadata(env, &classpath)?;

    println!(
        "jvm up: {} jars on the classpath, {} {} entrypoint(s)",
        classpath.len(),
        entry_kind,
        entry_specs.len()
    );
    // Read the hand-off back: it proves the loader will see those jars as mods
    // (or that the run supplied none), without guessing from the option list.
    println!("{}", report_fabric_add_mods(env));
    if !pre_launch.is_empty() {
        println!("{} preLaunch entrypoint(s)", pre_launch.len());
    }
    for line in &mixin_report {
        println!("{line}");
    }
    // One line per config this side leaves out, so a client/server split is
    // visible instead of a config silently disappearing.
    for line in &mixin_skipped {
        println!("{line}");
    }
    println!("{}", mixin_configs_line(mixin_registered));
    // Mixin's hand-off follows the config report in Fabric's order: the static
    // bootstrap, then one `Mixins.addConfiguration` per config. A run with no
    // config has no stage, reports that, and loads no Mixin class at all.
    let stages = mixin_stages(mixin_registered);
    if stages.is_empty() {
        println!("mixin bootstrap: no configs");
    }
    let mut bootstrap = None;
    for stage in stages {
        match stage {
            MixinStage::Bootstrap => {
                let outcome = mixin_bootstrap_label(env);
                println!("mixin bootstrap: {}", mixin_bootstrap_line(&outcome));
                bootstrap = Some(outcome);
            }
            MixinStage::Registration => {
                let mut registrar = JniMixinRegistrar::new(&mut *env);
                for line in register_mixin_configs(bootstrap.as_ref(), &mixin_names, &mut registrar)
                {
                    println!("{line}");
                }
            }
        }
    }
    // The loading phase ends here, before the first entrypoint: real launches
    // finish loading and select the environment's side once the loader has
    // registered its configs. A run with no stage never reached Mixin, so it
    // must not load a Mixin class for the phase either.
    if !stages.is_empty() {
        let side = MixinSide::selected(&entry_kind);
        let mut driver = JniMixinPhase { env: &mut *env };
        for line in run_mixin_phase(bootstrap.as_ref(), side, &mut driver) {
            println!("{line}");
        }
    }
    // The `String` a NeoForge entrypoint constructor receives is the jar's
    // `modId`; read it once from the metadata the run already reports.
    let neoforge_mod_id = constructor_only_entry_kind(&entry_kind)
        .then(|| neoforge_metadata(Path::new(&args[0])).ok())
        .flatten()
        .and_then(|metadata| metadata.mod_ids.into_iter().next());
    // Fabric runs loader-level `preLaunch` callbacks before the selected
    // environment's entrypoints; NeoForge has none and stays constructor-only.
    let mut work: Vec<(&str, &str)> = pre_launch
        .iter()
        .map(|spec| ("preLaunch", spec.as_str()))
        .collect();
    work.extend(
        entry_specs
            .iter()
            .map(|spec| (entry_kind.as_str(), spec.as_str())),
    );
    for (entry_kind, entry_spec) in work {
        let (entry, explicit_initializer) = split_entrypoint(entry_spec);
        let has_explicit_initializer = explicit_initializer.is_some();
        let (initializer, initializer_label) = if let Some(method) = explicit_initializer {
            (method.to_owned(), method.to_owned())
        } else if constructor_only_entry_kind(entry_kind) {
            (String::new(), "constructor".to_owned())
        } else {
            let (method, label) = initializer_for_kind(entry_kind)?;
            (method.to_owned(), label.to_owned())
        };
        let class = match env.find_class(entry.replace('.', "/")) {
            Ok(class) => class,
            Err(e) => return describe(env, "find_class", entry, e),
        };
        if constructor_only_entry_kind(entry_kind) && !has_explicit_initializer {
            let object = invoke_neoforge_constructor(
                env,
                &class,
                &classpath,
                entry,
                neoforge_mod_id.as_deref(),
                neoforge_dist(entry_kind),
            )?;
            call_mixin_on_load(env, &class, &object, entry)?;
            println!("{entry} constructor returned");
            continue;
        }
        // Fabric invokes a mod's common initializer before a `Class::method`
        // client/server entrypoint when both are declared on the same class. A
        // number of real mods use that method to publish their singleton state.
        // `preLaunch` is a loader-level callback, so it skips that bootstrap.
        if has_explicit_initializer && initializer != "onInitialize" && entry_kind != "preLaunch" {
            if env.get_method_id(&class, "onInitialize", "()V").is_ok() {
                let common = match env.new_object(&class, "()V", &[]) {
                    Ok(object) => object,
                    Err(e) => return describe(env, "new", entry, e),
                };
                call_mixin_on_load(env, &class, &common, entry)?;
                if let Err(e) = env.call_method(&common, "onInitialize", "()V", &[]) {
                    return describe(env, "onInitialize", entry, e);
                }
            } else {
                let _ = env.exception_clear();
            }
        }
        if has_explicit_initializer
            && env
                .get_static_method_id(&class, &initializer, "()V")
                .is_ok()
        {
            match env.call_static_method(&class, &initializer, "()V", &[]) {
                Ok(_) => {
                    println!("{initializer_label} returned");
                }
                Err(e) => return describe(env, &initializer_label, entry, e),
            }
            continue;
        }
        let _ = env.exception_clear();
        let object = match env.new_object(&class, "()V", &[]) {
            Ok(object) => object,
            Err(e) => return describe(env, "new", entry, e),
        };
        call_mixin_on_load(env, &class, &object, entry)?;
        if env.get_method_id(&class, &initializer, "()V").is_err() {
            let _ = env.exception_clear();
            if entry_kind == "main" && !has_explicit_initializer {
                println!("{entry} constructor returned (no {initializer} method)");
                continue;
            }
            return Err(format!(
                "{entry} has no {initializer}()V initializer for --entry-kind {entry_kind}"
            ));
        }
        match env.call_method(&object, &initializer, "()V", &[]) {
            Ok(_) => println!("{initializer_label} returned"),
            Err(e) => return describe(env, &initializer_label, entry, e),
        }
    }
    Ok(())
}

/// Entrypoint kinds that select Fabric's data-generation callback.
fn is_datagen_kind(kind: &str) -> bool {
    matches!(kind, "datagen" | "fabric-datagen" | "data")
}

/// The `entrypoints.<kind>` groups a datagen run accepts: Fabric's spelling and
/// the hand-written/Quilt one.
const DATAGEN_ENTRYPOINT_KINDS: [&str; 2] = ["fabric-datagen", "datagen"];
const FABRIC_DATAGEN_OUTPUT: &str = "fabric.datagen.output";

/// `-Dfabric.datagen.output=<dir>`, or nothing when the flag was not passed.
fn datagen_jvm_options(output: Option<&Path>) -> Vec<String> {
    output
        .map(|dir| vec![format!("-D{}={}", FABRIC_DATAGEN_OUTPUT, dir.display())])
        .unwrap_or_default()
}

const DATAGEN_GENERATOR_CLASS: &str = "net/fabricmc/fabric/api/datagen/v1/FabricDataGenerator";
const DATAGEN_OUTPUT_CLASS: &str = "net/fabricmc/fabric/api/datagen/v1/FabricDataOutput";
const MOD_CONTAINER_CLASS: &str = "net/fabricmc/loader/api/ModContainer";
const DATAGEN_INIT_SIG: &str = "(Lnet/fabricmc/fabric/api/datagen/v1/FabricDataGenerator;)V";
const DATAGEN_OUTPUT_CTOR: &str = "(Lnet/fabricmc/loader/api/ModContainer;Ljava/nio/file/Path;Z)V";
const DATAGEN_GENERATOR_CTOR: &str = "(Lnet/fabricmc/fabric/api/datagen/v1/FabricDataOutput;Lnet/fabricmc/loader/api/ModContainer;)V";
const MOD_CONTAINER_HORIZON_SIG: &str =
    "(Ljava/lang/String;Ljava/lang/String;)Lnet/fabricmc/loader/api/ModContainer;";
const DATAGEN_PROVIDERS: &str = "horizonProviders";
const DATAGEN_PROVIDERS_SIG: &str = "()Ljava/util/List;";
const MAX_DATAGEN_PROVIDERS: usize = 256;

/// The error a run without the façade's datagen slice reports; `main` turns it
/// into `error: ...` and a non-zero exit.
fn datagen_shim_unavailable(class: &str) -> String {
    format!("datagen: shim unavailable ({class} is not on the classpath)")
}

fn datagen_providers_line(count: usize) -> String {
    format!("datagen providers: {count}")
}

/// One `datagen provider N: pack/id (kind)` line, in registration order.
fn datagen_provider_line(index: usize, pack: &str, id: &str, kind: &str) -> String {
    format!("datagen provider {}: {pack}/{id} ({kind})", index + 1)
}

/// A class the shim slice must carry, cleared of a pending lookup failure.
fn datagen_class<'local>(env: &mut JNIEnv<'local>, name: &str) -> Result<JClass<'local>, String> {
    match env.find_class(name) {
        Ok(class) => Ok(class),
        Err(_) => {
            let _ = env.exception_clear();
            Err(datagen_shim_unavailable(name))
        }
    }
}

/// Datagen runs the `fabric-datagen` callback only. The JVM is started here so
/// no client/server/main initializer or Mixin phase can run: those are planned
/// after this branch in [`run`].
fn run_datagen(
    classpath: &[PathBuf],
    entries: &[String],
    output: Option<&Path>,
    heap: &str,
    nested: &NestedJars,
    metadata: Option<&(String, String)>,
) -> Result<(), String> {
    let output_dir = output.map_or_else(
        || std::env::temp_dir().join("horizon-datagen"),
        Path::to_path_buf,
    );
    let paths = std::env::join_paths(classpath).map_err(|e| e.to_string())?;
    let mut init = InitArgsBuilder::new()
        .version(JNIVersion::V8)
        .option(format!("-Djava.class.path={}", paths.to_string_lossy()))
        .option(heap)
        .option("-Djava.awt.headless=true");
    for option in datagen_jvm_options(output) {
        init = init.option(option);
    }
    let init = init.build().map_err(|e| format!("JVM options: {e}"))?;
    let jvm = JavaVM::new(init)
        .map_err(|e| format!("could not start a JVM ({e}); set JAVA_HOME to a JDK with libjvm"))?;
    let mut guard = jvm
        .attach_current_thread()
        .map_err(|e| format!("attach: {e}"))?;
    let env = &mut *guard;
    prepare_fabric_loader(env, &nested.root)?;
    seed_fabric_metadata(env, classpath)?;
    let generator = new_datagen_generator(env, &output_dir, metadata)?;
    println!("datagen output: {}", output_dir.display());
    for entry in entries {
        invoke_datagen_entry(env, &generator, entry)?;
    }
    for line in report_datagen_providers(env, &generator)? {
        println!("{line}");
    }
    Ok(())
}

/// Build the façade's `FabricDataGenerator` from `FabricDataOutput` and the
/// loader slice's `ModContainer.horizon(id, version)`. A classpath without the
/// shim fails with [`datagen_shim_unavailable`] before any entrypoint runs.
fn new_datagen_generator<'local>(
    env: &mut JNIEnv<'local>,
    output: &Path,
    metadata: Option<&(String, String)>,
) -> Result<JObject<'local>, String> {
    let generator = datagen_class(env, DATAGEN_GENERATOR_CLASS)?;
    let output_class = datagen_class(env, DATAGEN_OUTPUT_CLASS)?;
    let container_class = datagen_class(env, MOD_CONTAINER_CLASS)?;
    if env
        .get_static_method_id(&container_class, "horizon", MOD_CONTAINER_HORIZON_SIG)
        .is_err()
    {
        let _ = env.exception_clear();
        return Err(datagen_shim_unavailable(&format!(
            "{MOD_CONTAINER_CLASS}.horizon"
        )));
    }
    let (id, version) = metadata.map_or(("minecraft", "26.3"), |(id, version)| {
        (id.as_str(), version.as_str())
    });
    let id = env
        .new_string(id)
        .map_err(|e| format!("datagen mod id: {e}"))?;
    let version = env
        .new_string(version)
        .map_err(|e| format!("datagen mod version: {e}"))?;
    let container = env
        .call_static_method(
            &container_class,
            "horizon",
            MOD_CONTAINER_HORIZON_SIG,
            &[
                JValue::Object(&JObject::from(id)),
                JValue::Object(&JObject::from(version)),
            ],
        )
        .map_err(|e| format!("datagen ModContainer: {e}"))?
        .l()
        .map_err(|e| format!("datagen ModContainer: {e}"))?;
    let paths = datagen_class(env, "java/nio/file/Paths")?;
    let output_text = env
        .new_string(output.to_string_lossy())
        .map_err(|e| format!("datagen output path: {e}"))?;
    let empty = env
        .new_object_array(0, "java/lang/String", JObject::null())
        .map_err(|e| format!("datagen output path: {e}"))?;
    let path = env
        .call_static_method(
            &paths,
            "get",
            "(Ljava/lang/String;[Ljava/lang/String;)Ljava/nio/file/Path;",
            &[
                JValue::Object(&JObject::from(output_text)),
                JValue::Object(&empty),
            ],
        )
        .map_err(|e| format!("datagen output path: {e}"))?
        .l()
        .map_err(|e| format!("datagen output path: {e}"))?;
    let output = env
        .new_object(
            &output_class,
            DATAGEN_OUTPUT_CTOR,
            &[
                JValue::Object(&container),
                JValue::Object(&path),
                JValue::Bool(0),
            ],
        )
        .map_err(|e| format!("datagen FabricDataOutput: {e}"))?;
    env.new_object(
        &generator,
        DATAGEN_GENERATOR_CTOR,
        &[JValue::Object(&output), JValue::Object(&container)],
    )
    .map_err(|e| format!("datagen FabricDataGenerator: {e}"))
}

/// One datagen entrypoint: a class implementing `DataGeneratorEntrypoint`, which
/// Fabric instantiates and hands the generator.
fn invoke_datagen_entry(
    env: &mut JNIEnv,
    generator: &JObject,
    entry_spec: &str,
) -> Result<(), String> {
    let (entry, method) = split_entrypoint(entry_spec);
    if method.is_some() {
        return Err(format!(
            "datagen entrypoint {entry_spec} names a method; pass --entry <class>"
        ));
    }
    let class = match env.find_class(entry.replace('.', "/")) {
        Ok(class) => class,
        Err(e) => return describe(env, "find_class", entry, e),
    };
    let object = match env.new_object(&class, "()V", &[]) {
        Ok(object) => object,
        Err(e) => return describe(env, "new", entry, e),
    };
    match env.call_method(
        &object,
        "onInitializeDataGenerator",
        DATAGEN_INIT_SIG,
        &[JValue::Object(generator)],
    ) {
        Ok(_) => println!("datagen: onInitializeDataGenerator returned"),
        Err(e) => return describe(env, "onInitializeDataGenerator", entry, e),
    }
    Ok(())
}

/// Read the shim's `horizonProviders()` ledger after the entrypoint returned:
/// one row per `addProvider`, in call order. A shim without the accessor (an
/// older façade) reports nothing instead of failing.
fn report_datagen_providers(env: &mut JNIEnv, generator: &JObject) -> Result<Vec<String>, String> {
    let class = env
        .get_object_class(generator)
        .map_err(|e| format!("datagen providers: {e}"))?;
    if env
        .get_method_id(&class, DATAGEN_PROVIDERS, DATAGEN_PROVIDERS_SIG)
        .is_err()
    {
        let _ = env.exception_clear();
        return Ok(Vec::new());
    }
    let list = env
        .call_method(generator, DATAGEN_PROVIDERS, DATAGEN_PROVIDERS_SIG, &[])
        .and_then(|value| value.l())
        .map_err(|e| format!("datagen providers: {e}"))?;
    let count = env
        .call_method(&list, "size", "()I", &[])
        .and_then(|value| value.i())
        .map_err(|e| format!("datagen providers: {e}"))?;
    let count = usize::try_from(count).unwrap_or(0);
    let mut lines = vec![datagen_providers_line(count)];
    for index in 0..count.min(MAX_DATAGEN_PROVIDERS) {
        let row = env
            .call_method(
                &list,
                "get",
                "(I)Ljava/lang/Object;",
                &[JValue::Int(index as i32)],
            )
            .and_then(|value| value.l())
            .map_err(|e| format!("datagen provider {index}: {e}"))?;
        let row = JObjectArray::from(row);
        if env.get_array_length(&row).unwrap_or(0) >= 3 {
            let pack = provider_text(env, &row, 0)?;
            let id = provider_text(env, &row, 1)?;
            let kind = provider_text(env, &row, 2)?;
            lines.push(datagen_provider_line(index, &pack, &id, &kind));
        }
    }
    if count > MAX_DATAGEN_PROVIDERS {
        lines.push(format!(
            "datagen providers: capped at {MAX_DATAGEN_PROVIDERS} of {count}"
        ));
    }
    Ok(lines)
}

/// One `{pack, id, kind, provider}` column as text; a null column (a shim that
/// retained no id) reads as `null` instead of failing the report.
fn provider_text(env: &mut JNIEnv, row: &JObjectArray, column: i32) -> Result<String, String> {
    let value = env
        .get_object_array_element(row, column)
        .map_err(|e| format!("datagen provider value: {e}"))?;
    if value.is_null() {
        return Ok("null".to_owned());
    }
    let text = env
        .get_string((&value).into())
        .map_err(|e| format!("datagen provider value: {e}"))?;
    Ok(text.to_string_lossy().into_owned())
}

fn split_entrypoint(spec: &str) -> (&str, Option<&str>) {
    spec.split_once("::")
        .map_or((spec, None), |(class, method)| (class, Some(method)))
}

fn constructor_only_entry_kind(kind: &str) -> bool {
    kind == "neoforge"
}

/// The parameter types a NeoForge entrypoint constructor may take. NeoForge
/// injects exactly these, so a constructor taking anything else cannot run here.
const NEOFORGE_DIST_TYPE: &str = "Lnet/neoforged/api/distmarker/Dist;";
const NEOFORGE_MOD_ID_TYPE: &str = "Ljava/lang/String;";
/// Loader objects the probe can name but not build: passed as `null`, which
/// makes a mod's first call on one the exact failure this probe exists to find.
const NEOFORGE_NULL_TYPES: [&str; 4] = [
    "Lnet/neoforged/bus/api/IEventBus;",
    "Lnet/neoforged/fml/ModContainer;",
    "Lnet/neoforged/fml/javafmlmod/FMLModContainer;",
    "Lnet/neoforged/fml/ModList;",
];
const NEOFORGE_DIST_CLASS: &str = "net/neoforged/api/distmarker/Dist";
const NO_ARG_CONSTRUCTOR: &str = "()V";

/// One NeoForge entrypoint constructor parameter.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum NeoforgeArg {
    /// The `Dist` constant for `--entry-kind`: `CLIENT`, or the dedicated side.
    Dist,
    /// The jar's `modId`.
    ModId,
    /// A loader object the runner cannot build yet, passed as `null`.
    Null,
}

/// The `Dist` constant an entrypoint constructor receives. `--entry-kind`
/// selects the side the same way it does for Mixin; the loader-lifecycle kinds
/// (`neoforge`, `main`) run as the client this probe models.
fn neoforge_dist(entry_kind: &str) -> MixinSide {
    MixinSide::selected(entry_kind).unwrap_or(MixinSide::Client)
}

/// What one constructor parameter receives, or `None` when the runner cannot
/// supply it (which disqualifies that constructor).
fn neoforge_arg(param: &str) -> Option<NeoforgeArg> {
    if param == NEOFORGE_DIST_TYPE {
        Some(NeoforgeArg::Dist)
    } else if param == NEOFORGE_MOD_ID_TYPE {
        Some(NeoforgeArg::ModId)
    } else if NEOFORGE_NULL_TYPES.contains(&param) {
        Some(NeoforgeArg::Null)
    } else {
        None
    }
}

/// The arguments `descriptor` takes, or `None` when a parameter is not one the
/// runner can supply.
fn neoforge_constructor_args(descriptor: &str) -> Option<Vec<NeoforgeArg>> {
    descriptor_params(descriptor)?
        .iter()
        .map(|param| neoforge_arg(param))
        .collect()
}

/// The widest constructor whose parameters are all injectable, ties broken by
/// descriptor text so class-file order never decides; `None` leaves the no-arg
/// one.
fn neoforge_constructor_descriptor(constructors: &[String]) -> Option<&str> {
    constructors
        .iter()
        .filter_map(|descriptor| {
            let args = neoforge_constructor_args(descriptor)?;
            Some((args.len(), descriptor.as_str()))
        })
        .max_by(|a, b| a.0.cmp(&b.0).then_with(|| b.1.cmp(a.1)))
        .map(|(_, descriptor)| descriptor)
}

/// The entrypoint constructor for `class`: the widest supported one, else
/// `()V`. An unreadable class file (not on the classpath, malformed, above
/// [`MAX_CLASS_FILE_BYTES`]) also lands on `()V`, so this never fails a run
/// that has a no-arg constructor.
fn neoforge_constructor(classpath: &[PathBuf], class: &str) -> String {
    class_file_bytes(classpath, class)
        .and_then(|bytes| parse_constructors(&bytes))
        .and_then(|constructors| neoforge_constructor_descriptor(&constructors).map(str::to_owned))
        .unwrap_or_else(|| NO_ARG_CONSTRUCTOR.to_owned())
}

/// `neoforge ctor: <descriptor>`, naming the constructor that ran.
fn neoforge_ctor_line(descriptor: &str) -> String {
    format!("neoforge ctor: {descriptor}")
}

/// The single line a link failure reports before the no-arg retry.
fn neoforge_ctor_fallback_line(descriptor: &str) -> String {
    format!("neoforge ctor: {descriptor} unavailable, retrying {NO_ARG_CONSTRUCTOR}")
}

/// Link failures that mean the JVM could not link the constructor the class
/// file named, which is what a façade without the loader classes reports.
fn link_failure(class: &str) -> bool {
    matches!(
        class,
        "java.lang.NoSuchMethodError" | "java.lang.AbstractMethodError"
    )
}

/// Whether a failed constructor attempt retries `()V`: only a link failure of a
/// non-no-arg descriptor does, so a run with a no-arg constructor never fails.
fn should_retry_no_arg(descriptor: &str, failure: Option<&str>) -> bool {
    descriptor != NO_ARG_CONSTRUCTOR && failure.is_some_and(link_failure)
}

/// Upper bound on one class file the scan reads: no unbounded allocation.
const MAX_CLASS_FILE_BYTES: u64 = 4 << 20;

/// The JVM's own array-dimension limit, so the splitter cannot loop on garbage.
const MAX_ARRAY_DIMENSIONS: usize = 255;

/// The class file bytes for a binary class name, in classpath order like the
/// JVM. Only the first match is read, and only up to [`MAX_CLASS_FILE_BYTES`];
/// anything else is `None`, which leaves the no-arg constructor.
fn class_file_bytes(classpath: &[PathBuf], class: &str) -> Option<Vec<u8>> {
    let entry = format!("{}.class", class.replace('.', "/"));
    for path in classpath {
        if path.is_dir() {
            let file = path.join(&entry);
            let Ok(metadata) = fs::metadata(&file) else {
                continue;
            };
            if !metadata.is_file() || metadata.len() > MAX_CLASS_FILE_BYTES {
                continue;
            }
            if let Ok(bytes) = fs::read(&file) {
                return Some(bytes);
            }
            continue;
        }
        let Ok(file) = File::open(path) else {
            continue;
        };
        let Ok(mut archive) = zip::ZipArchive::new(file) else {
            continue;
        };
        let Ok(mut member) = archive.by_name(&entry) else {
            continue;
        };
        if member.size() > MAX_CLASS_FILE_BYTES {
            continue;
        }
        let mut bytes = Vec::new();
        if std::io::Read::read_to_end(&mut member, &mut bytes).is_ok() {
            return Some(bytes);
        }
    }
    None
}

/// A bounded class-file cursor: every read checks the remaining bytes, so a
/// truncated or hostile file fails instead of panicking.
struct ClassReader<'a> {
    bytes: &'a [u8],
    at: usize,
}

impl<'a> ClassReader<'a> {
    fn take(&mut self, len: usize) -> Option<&'a [u8]> {
        let end = self.at.checked_add(len)?;
        let bytes = self.bytes.get(self.at..end)?;
        self.at = end;
        Some(bytes)
    }

    fn u1(&mut self) -> Option<u8> {
        Some(*self.take(1)?.first()?)
    }

    fn u2(&mut self) -> Option<u16> {
        let bytes = self.take(2)?;
        Some(u16::from_be_bytes([bytes[0], bytes[1]]))
    }

    fn u4(&mut self) -> Option<u32> {
        let bytes = self.take(4)?;
        Some(u32::from_be_bytes([bytes[0], bytes[1], bytes[2], bytes[3]]))
    }

    fn skip(&mut self, len: usize) -> Option<()> {
        self.take(len).map(|_| ())
    }
}

/// The `<init>` descriptors a class file declares, in declaration order.
/// Total by construction: a malformed or truncated file is `None`, and every
/// index is checked against the constant pool.
fn parse_constructors(bytes: &[u8]) -> Option<Vec<String>> {
    let mut reader = ClassReader { bytes, at: 0 };
    if reader.u4()? != 0xCAFE_BABE {
        return None;
    }
    reader.skip(4)?; // minor_version, major_version
    let pool = constant_pool(&mut reader)?;
    reader.skip(6)?; // access_flags, this_class, super_class
    let interfaces = reader.u2()? as usize;
    reader.skip(interfaces.checked_mul(2)?)?;
    let fields = reader.u2()? as usize;
    for _ in 0..fields {
        skip_member(&mut reader)?;
    }
    let methods = reader.u2()? as usize;
    let mut constructors = Vec::new();
    for _ in 0..methods {
        let (name, descriptor) = member_header(&mut reader)?;
        if pool.get(name as usize).copied().flatten() == Some("<init>") {
            let descriptor = pool.get(descriptor as usize).copied().flatten()?;
            constructors.push(descriptor.to_owned());
        }
        skip_attributes(&mut reader)?;
    }
    skip_attributes(&mut reader)?; // the class's own attributes
    Some(constructors)
}

/// The `Utf8` entries of a constant pool, indexed by constant-pool index.
/// Other entries are skipped by their fixed tag length; long and double take
/// two slots, as in the class-file format.
fn constant_pool<'a>(reader: &mut ClassReader<'a>) -> Option<Vec<Option<&'a str>>> {
    let count = reader.u2()? as usize;
    if count == 0 {
        return None;
    }
    let mut pool: Vec<Option<&'a str>> = vec![None; count];
    let mut index = 1;
    while index < count {
        match reader.u1()? {
            1 => {
                let len = reader.u2()? as usize;
                pool[index] = Some(std::str::from_utf8(reader.take(len)?).ok()?);
            }
            3 | 4 => reader.skip(4)?,
            // Long and double occupy two constant-pool slots.
            5 | 6 => {
                reader.skip(8)?;
                index += 1;
            }
            7 | 8 | 16 | 19 | 20 => reader.skip(2)?,
            9 | 10 | 11 | 12 | 17 | 18 => reader.skip(4)?,
            15 => reader.skip(3)?,
            _ => return None,
        }
        index += 1;
    }
    Some(pool)
}

/// A field or method's `(name_index, descriptor_index)` pair.
fn member_header(reader: &mut ClassReader) -> Option<(u16, u16)> {
    reader.skip(2)?; // access_flags
    let name = reader.u2()?;
    let descriptor = reader.u2()?;
    Some((name, descriptor))
}

/// One field, which the constructor scan does not need.
fn skip_member(reader: &mut ClassReader) -> Option<()> {
    reader.skip(6)?; // access_flags, name_index, descriptor_index
    skip_attributes(reader)
}

/// `attribute_count` followed by each `(name_index, length)` and its bytes.
fn skip_attributes(reader: &mut ClassReader) -> Option<()> {
    let count = reader.u2()? as usize;
    for _ in 0..count {
        reader.skip(2)?;
        let len = usize::try_from(reader.u4()?).ok()?;
        reader.skip(len)?;
    }
    Some(())
}

/// Splits a method descriptor into its parameter type descriptors. `None` for
/// anything that is not a well-formed `(...)R` descriptor.
fn descriptor_params(descriptor: &str) -> Option<Vec<&str>> {
    let (params, _) = descriptor.strip_prefix('(')?.split_once(')')?;
    let mut out = Vec::new();
    let mut rest = params;
    while !rest.is_empty() {
        let (param, remainder) = split_type(rest)?;
        out.push(param);
        rest = remainder;
    }
    Some(out)
}

/// One type descriptor at the start of `text`, with the rest of `text`.
fn split_type(text: &str) -> Option<(&str, &str)> {
    let bytes = text.as_bytes();
    let mut start = 0;
    while bytes.get(start) == Some(&b'[') {
        start += 1;
        if start > MAX_ARRAY_DIMENSIONS {
            return None;
        }
    }
    let element = text.get(start..)?;
    let len = match element.as_bytes().first()? {
        b'L' => element.find(';')? + 1,
        b'B' | b'C' | b'D' | b'F' | b'I' | b'J' | b'S' | b'Z' => 1,
        _ => return None,
    };
    let end = start.checked_add(len)?;
    Some((text.get(..end)?, text.get(end..)?))
}

/// The `Dist` field names a constructor receives. NeoForge names the dedicated
/// side `DEDICATED_SERVER`; the bare `SERVER` spelling is tried second so a
/// build using either name works.
fn neoforge_dist_fields(side: MixinSide) -> &'static [&'static str] {
    match side {
        MixinSide::Client => &["CLIENT"],
        MixinSide::Server => &["DEDICATED_SERVER", "SERVER"],
    }
}

/// The `Dist` constant for `side`, or `null` when the façade carries neither the
/// class nor the field: the constructor still runs instead of the probe failing.
fn dist_constant<'local>(env: &mut JNIEnv<'local>, side: MixinSide) -> JObject<'local> {
    let Ok(class) = env.find_class(NEOFORGE_DIST_CLASS) else {
        let _ = env.exception_clear();
        return JObject::null();
    };
    for field in neoforge_dist_fields(side) {
        if let Ok(value) = env.get_static_field(&class, *field, NEOFORGE_DIST_TYPE) {
            if let Ok(value) = value.l() {
                return value;
            }
        }
        // A field this build does not have must not leave a throwable behind
        // for the constructor call.
        let _ = env.exception_clear();
    }
    JObject::null()
}

/// The objects one NeoForge constructor call passes, in parameter order.
fn neoforge_ctor_objects<'local>(
    env: &mut JNIEnv<'local>,
    args: &[NeoforgeArg],
    side: MixinSide,
    mod_id: Option<&str>,
) -> Vec<JObject<'local>> {
    let mut objects = Vec::with_capacity(args.len());
    for arg in args {
        objects.push(match arg {
            NeoforgeArg::Dist => dist_constant(env, side),
            NeoforgeArg::ModId => match mod_id {
                Some(id) => match env.new_string(id) {
                    Ok(id) => JObject::from(id),
                    Err(_) => {
                        let _ = env.exception_clear();
                        JObject::null()
                    }
                },
                None => JObject::null(),
            },
            NeoforgeArg::Null => JObject::null(),
        });
    }
    objects
}

/// Run a NeoForge entrypoint's constructor, retried as the no-arg one when the
/// JVM cannot link it. The line naming a constructor is printed only once the
/// call was accepted, so a fallback reads as one failure line then the retry.
fn invoke_neoforge_constructor<'local>(
    env: &mut JNIEnv<'local>,
    class: &JClass<'local>,
    classpath: &[PathBuf],
    entry: &str,
    mod_id: Option<&str>,
    side: MixinSide,
) -> Result<JObject<'local>, String> {
    let descriptor = neoforge_constructor(classpath, entry);
    let args = neoforge_constructor_args(&descriptor).unwrap_or_default();
    let objects = neoforge_ctor_objects(env, &args, side, mod_id);
    let values: Vec<JValue> = objects.iter().map(JValue::Object).collect();
    match env.new_object(class, descriptor.as_str(), &values) {
        Ok(object) => {
            println!("{}", neoforge_ctor_line(&descriptor));
            Ok(object)
        }
        Err(error) => {
            let failure = pending_throwable_class(env);
            if !should_retry_no_arg(&descriptor, failure.as_deref()) {
                return Err(describe_error(env, "new", entry, error));
            }
            let _ = env.exception_clear();
            println!("{}", neoforge_ctor_fallback_line(&descriptor));
            match env.new_object(class, NO_ARG_CONSTRUCTOR, &[]) {
                Ok(object) => Ok(object),
                Err(error) => Err(describe_error(env, "new", entry, error)),
            }
        }
    }
}

fn call_mixin_on_load(
    env: &mut JNIEnv,
    class: &JClass,
    object: &JObject,
    entry: &str,
) -> Result<(), String> {
    if env
        .get_method_id(class, "onLoad", "(Ljava/lang/String;)V")
        .is_err()
    {
        let _ = env.exception_clear();
        return Ok(());
    }
    let package = entry.rsplit_once('.').map_or(entry, |(package, _)| package);
    let package = env
        .new_string(package)
        .map_err(|e| format!("Mixin onLoad package: {e}"))?;
    let package = JObject::from(package);
    env.call_method(
        object,
        "onLoad",
        "(Ljava/lang/String;)V",
        &[JValue::Object(&package)],
    )
    .map(|_| ())
    .map_err(|e| format!("Mixin onLoad {entry}: {e}"))
}

fn seed_fabric_metadata(env: &mut JNIEnv, classpath: &[PathBuf]) -> Result<(), String> {
    if env
        .find_class("net/fabricmc/loader/impl/FabricLoaderImpl")
        .is_err()
    {
        let _ = env.exception_clear();
        return Ok(());
    }
    let bridge = match env.find_class("HorizonLoaderBridge") {
        Ok(class) => class,
        Err(_) => {
            let _ = env.exception_clear();
            return Ok(());
        }
    };
    for path in classpath {
        let Some((id, version)) = fabric_metadata(path) else {
            continue;
        };
        let id = env
            .new_string(id)
            .map_err(|e| format!("Fabric metadata id: {e}"))?;
        let version = env
            .new_string(version)
            .map_err(|e| format!("Fabric metadata version: {e}"))?;
        env.call_static_method(
            &bridge,
            "seed",
            "(Ljava/lang/String;Ljava/lang/String;)V",
            &[JValue::Object(&id.into()), JValue::Object(&version.into())],
        )
        .map_err(|e| format!("Fabric metadata seed for {}: {e}", path.display()))?;
    }
    Ok(())
}

fn fabric_metadata(path: &Path) -> Option<(String, String)> {
    let file = File::open(path).ok()?;
    let mut archive = zip::ZipArchive::new(file).ok()?;
    let mut metadata = archive.by_name("fabric.mod.json").ok()?;
    let mut text = String::new();
    std::io::Read::read_to_string(&mut metadata, &mut text).ok()?;
    let value: serde_json::Value = serde_json::from_str(&text).ok()?;
    let id = value.get("id")?.as_str()?.to_owned();
    let version = match value.get("version") {
        Some(serde_json::Value::String(version)) => version.clone(),
        Some(serde_json::Value::Object(version)) => version
            .get("semver")
            .or_else(|| version.get("raw"))
            .and_then(serde_json::Value::as_str)
            .unwrap_or("0")
            .to_owned(),
        _ => "0".to_owned(),
    };
    Some((id, version))
}

/// Fabric's documented developer property for classpath mods, and the loader
/// flags this probe may forward. The loader reads them before any entrypoint
/// runs, so they have to be in the JVM options.
const FABRIC_ADD_MODS: &str = "fabric.addMods";
const FABRIC_DEVELOPMENT: &str = "fabric.development";
const FABRIC_SKIP_MC_PROVIDER: &str = "fabric.skipMcProvider";

/// Upper bounds for `-Dfabric.addMods`: the list is one JVM argument, so a
/// hostile or accidental thousand-jar command line must not grow without bound.
const MAX_FABRIC_ADD_MODS: usize = 256;
const MAX_FABRIC_ADD_MODS_BYTES: usize = 32 * 1024;

/// The platform path separator, what Java's `File.pathSeparator` reports and
/// the character Fabric splits `fabric.addMods` on.
fn classpath_separator() -> char {
    if cfg!(windows) { ';' } else { ':' }
}

/// The value of `-Dfabric.addMods`: the supplied jars joined with
/// [`classpath_separator`], sorted and deduplicated so the value never depends
/// on argument order. Only paths from `jars` can appear (nothing is scanned
/// from disk), a path carrying the separator is dropped because the property
/// cannot express it, and the list stops at [`MAX_FABRIC_ADD_MODS`] entries or
/// [`MAX_FABRIC_ADD_MODS_BYTES`] bytes.
fn fabric_add_mods(jars: &[PathBuf]) -> Option<String> {
    let separator = classpath_separator();
    let mut paths: Vec<String> = jars
        .iter()
        .map(|jar| jar.to_string_lossy().into_owned())
        .filter(|path| !path.is_empty() && !path.contains(separator))
        .collect();
    paths.sort();
    paths.dedup();
    paths.truncate(MAX_FABRIC_ADD_MODS);
    let mut value = String::new();
    for path in paths {
        let separator_len = usize::from(!value.is_empty());
        if value.len() + separator_len + path.len() > MAX_FABRIC_ADD_MODS_BYTES {
            break;
        }
        if separator_len == 1 {
            value.push(separator);
        }
        value.push_str(&path);
    }
    (!value.is_empty()).then_some(value)
}

/// How many jars the property carries, for the deterministic log line. A
/// missing or empty property has none.
fn fabric_add_mods_count(value: Option<&str>) -> usize {
    value.map_or(0, |value| {
        value
            .split(classpath_separator())
            .filter(|path| !path.is_empty())
            .count()
    })
}

/// `fabric addMods: N jar(s)`, the one-line diagnostic for the hand-off.
fn fabric_add_mods_line(count: usize) -> String {
    format!("fabric addMods: {count} jar(s)")
}

/// The JVM options Fabric's developer properties need, in a stable order. Kept
/// as an argument list so a test can inspect the exact properties without
/// starting a JVM. `fabric.development` is opt-in, and `fabric.skipMcProvider`
/// is only forwarded when the environment already set it.
fn fabric_jvm_options(
    add_mods: Option<&str>,
    development: bool,
    skip_mc_provider: bool,
) -> Vec<String> {
    let mut options = Vec::new();
    if let Some(add_mods) = add_mods {
        options.push(format!("-D{}={add_mods}", FABRIC_ADD_MODS));
    }
    if development {
        options.push(format!("-D{}=true", FABRIC_DEVELOPMENT));
    }
    if skip_mc_provider {
        options.push(format!("-D{}=true", FABRIC_SKIP_MC_PROVIDER));
    }
    options
}

/// The launcher-side JVM option strings the environment already carries. Those
/// three variables are the only way a system property can be seeded before the
/// JVM starts, which is what "already set in the environment" means here.
fn fabric_environment_options() -> Vec<String> {
    ["JAVA_TOOL_OPTIONS", "_JAVA_OPTIONS", "JDK_JAVA_OPTIONS"]
        .iter()
        .filter_map(|name| std::env::var(name).ok())
        .collect()
}

/// Whether the environment already asks Fabric to skip its Minecraft provider.
/// The probe never invents it: a run only forwards what a launcher put there.
fn skip_mc_provider_requested(options: &[String]) -> bool {
    options
        .iter()
        .any(|option| option.contains(FABRIC_SKIP_MC_PROVIDER))
}

/// `System.getProperty(name)`, or `None` when the JVM does not have it. Read
/// after the JVM started, so this is diagnostics and never a failure.
fn jvm_property(env: &mut JNIEnv, name: &str) -> Option<String> {
    let value = system_property(env, name);
    // A failed lookup must not leave a throwable pending for the entrypoints.
    if value.is_none() {
        let _ = env.exception_clear();
    }
    value
}

/// The raw `System.getProperty` call behind [`jvm_property`].
fn system_property(env: &mut JNIEnv, name: &str) -> Option<String> {
    let system = env.find_class("java/lang/System").ok()?;
    let key = env.new_string(name).ok()?;
    let key = JObject::from(key);
    let value = env
        .call_static_method(
            &system,
            "getProperty",
            "(Ljava/lang/String;)Ljava/lang/String;",
            &[JValue::Object(&key)],
        )
        .ok()?
        .l()
        .ok()?;
    if value.is_null() {
        return None;
    }
    let text = env.get_string((&value).into()).ok()?;
    Some(text.to_string_lossy().into_owned())
}

/// The `fabric addMods` diagnostic, read back from the started JVM. A property
/// that did not survive reports 0 jars instead of failing the probe.
fn report_fabric_add_mods(env: &mut JNIEnv) -> String {
    let value = jvm_property(env, FABRIC_ADD_MODS);
    fabric_add_mods_line(fabric_add_mods_count(value.as_deref()))
}

/// Give Fabric Loader the two paths it normally receives from its launcher.
/// The embedded runner does not execute Fabric's full game provider, so the
/// singleton's private fields would otherwise remain null and any client mod
/// touching `FabricLoader#getConfigDir()` would panic. A missing loader jar is
/// fine: NeoForge and direct entrypoint probes do not have this class.
fn prepare_fabric_loader(env: &mut JNIEnv, root: &Path) -> Result<(), String> {
    let loader = match env.find_class("net/fabricmc/loader/impl/FabricLoaderImpl") {
        Ok(class) => class,
        Err(_) => {
            let _ = env.exception_clear();
            return Ok(());
        }
    };
    let game_dir = root.join("game");
    let config_dir = root.join("config");
    fs::create_dir_all(&game_dir).map_err(|e| format!("{}: {e}", game_dir.display()))?;
    fs::create_dir_all(&config_dir).map_err(|e| format!("{}: {e}", config_dir.display()))?;
    let instance = env
        .get_static_field(
            &loader,
            "INSTANCE",
            "Lnet/fabricmc/loader/impl/FabricLoaderImpl;",
        )
        .map_err(|e| format!("Fabric Loader INSTANCE: {e}"))?
        .l()
        .map_err(|e| format!("Fabric Loader INSTANCE value: {e}"))?;
    set_loader_path(env, &loader, &instance, "gameDir", &game_dir)?;
    set_loader_path(env, &loader, &instance, "configDir", &config_dir)?;
    Ok(())
}

fn set_loader_path(
    env: &mut JNIEnv,
    loader: &JObject,
    instance: &JObject,
    field_name: &str,
    path: &Path,
) -> Result<(), String> {
    let name = env
        .new_string(field_name)
        .map_err(|e| format!("Fabric Loader field name: {e}"))?;
    let name = JObject::from(name);
    let field = env
        .call_method(
            loader,
            "getDeclaredField",
            "(Ljava/lang/String;)Ljava/lang/reflect/Field;",
            &[JValue::Object(&name)],
        )
        .map_err(|e| format!("Fabric Loader field {field_name}: {e}"))?
        .l()
        .map_err(|e| format!("Fabric Loader field {field_name} value: {e}"))?;
    env.call_method(&field, "setAccessible", "(Z)V", &[JValue::Bool(1)])
        .map_err(|e| format!("Fabric Loader field {field_name} access: {e}"))?;
    let path_text = env
        .new_string(path.to_string_lossy())
        .map_err(|e| format!("Fabric Loader path {field_name}: {e}"))?;
    let path_text = JObject::from(path_text);
    let file_class = env
        .find_class("java/io/File")
        .map_err(|e| format!("java.io.File: {e}"))?;
    let file = env
        .new_object(
            &file_class,
            "(Ljava/lang/String;)V",
            &[JValue::Object(&path_text)],
        )
        .map_err(|e| format!("java.io.File {field_name}: {e}"))?;
    let value = env
        .call_method(&file, "toPath", "()Ljava/nio/file/Path;", &[])
        .map_err(|e| format!("Fabric Loader path {field_name}: {e}"))?
        .l()
        .map_err(|e| format!("Fabric Loader path {field_name} value: {e}"))?;
    env.call_method(
        &field,
        "set",
        "(Ljava/lang/Object;Ljava/lang/Object;)V",
        &[JValue::Object(instance), JValue::Object(&value)],
    )
    .map_err(|e| format!("Fabric Loader field {field_name} set: {e}"))?;
    Ok(())
}

fn initializer_for_kind(kind: &str) -> Result<(&'static str, &'static str), String> {
    match kind {
        "main" | "init" => Ok(("onInitialize", "onInitialize")),
        "client" | "client_init" => Ok(("onInitializeClient", "onInitializeClient")),
        "server" | "server_init" => Ok(("onInitializeServer", "onInitializeServer")),
        "preLaunch" | "prelaunch" => Ok(("onPreLaunch", "onPreLaunch")),
        other => Err(format!(
            "invalid --entry-kind {other}; expected main, client, server, preLaunch, neoforge, or datagen"
        )),
    }
}

/// Prints the Java exception (with its chain), and says where it happened.
fn describe(
    env: &mut JNIEnv,
    stage: &str,
    entry: &str,
    error: jni::errors::Error,
) -> Result<(), String> {
    Err(describe_error(env, stage, entry, error))
}

/// The message [`describe`] reports, for a caller that keeps running.
fn describe_error(env: &mut JNIEnv, stage: &str, entry: &str, error: jni::errors::Error) -> String {
    let fallback = (error.to_string() == "Java exception was thrown")
        .then(|| exception_fallback(env))
        .flatten();
    let _ = env.exception_describe();
    let _ = env.exception_clear();
    if let Some(message) = fallback {
        return format!("{stage} {entry}: {message}");
    }
    format!("{stage} {entry}: {error}")
}

/// The class name of the throwable the JVM left pending, without clearing it.
/// The caller decides whether it is a link failure or gets described.
fn pending_throwable_class(env: &mut JNIEnv) -> Option<String> {
    let throwable = env.exception_occurred().ok()?;
    let class = env.get_object_class(&throwable).ok()?;
    let name = env
        .call_method(&class, "getName", "()Ljava/lang/String;", &[])
        .ok()?
        .l()
        .ok()?;
    let name = env.get_string((&name).into()).ok()?;
    Some(name.to_string_lossy().into_owned())
}

/// Turn the exceptions that mean "the native façade cannot handle this" into
/// an explicit JVM fallback diagnostic. Dynamic classpath/resource lookups
/// stay on HotSpot, so a mod can tell this is a deliberate fallback rather
/// than an opaque entrypoint failure.
fn exception_fallback(env: &mut JNIEnv) -> Option<String> {
    let name = pending_throwable_class(env)?;
    let throwable = env.exception_occurred().ok()?;
    let message = env
        .call_method(&throwable, "getMessage", "()Ljava/lang/String;", &[])
        .ok()
        .and_then(|value| value.l().ok())
        .and_then(|value| {
            let text = env.get_string((&value).into()).ok()?;
            Some(text.to_string_lossy().into_owned())
        });
    let detail = message.filter(|value| !value.is_empty());
    fallback_label(&name, detail.as_deref())
}

fn fallback_label(class: &str, detail: Option<&str>) -> Option<String> {
    match class {
        "java.lang.UnsupportedOperationException" | "java.lang.SecurityException" => Some(format!(
            "JVM fallback selected for unsupported native call{}",
            detail.map_or_else(String::new, |value| format!(": {value}"))
        )),
        "java.lang.ClassNotFoundException" | "java.lang.NoClassDefFoundError" => Some(format!(
            "JVM fallback selected for dynamic classpath lookup{}",
            detail.map_or_else(String::new, |value| format!(": {value}"))
        )),
        "java.lang.NoSuchMethodError"
        | "java.lang.NoSuchFieldError"
        | "java.lang.NoSuchMethodException"
        | "java.lang.NoSuchFieldException"
        | "java.lang.AbstractMethodError"
        | "java.lang.IncompatibleClassChangeError" => Some(format!(
            "JVM fallback selected for missing façade member{}",
            detail.map_or_else(String::new, |value| format!(": {value}"))
        )),
        "java.lang.ExceptionInInitializerError" | "java.lang.LinkageError" => Some(format!(
            "JVM fallback selected for static initialization failure{}",
            detail.map_or_else(String::new, |value| format!(": {value}"))
        )),
        "java.lang.UnsatisfiedLinkError" => Some(format!(
            "JVM fallback selected for native linkage failure{}",
            detail.map_or_else(String::new, |value| format!(": {value}"))
        )),
        "java.lang.VerifyError"
        | "java.lang.ClassFormatError"
        | "java.lang.BootstrapMethodError"
        | "java.lang.IllegalAccessError"
        | "java.lang.InstantiationError" => Some(format!(
            "JVM fallback selected for runtime linkage failure{}",
            detail.map_or_else(String::new, |value| format!(": {value}"))
        )),
        _ => None,
    }
}

const FML_PROBE_SOURCE: &str = r#"
package horizon;

import java.nio.file.*;
import java.util.*;
import net.neoforged.api.distmarker.Dist;
import net.neoforged.fml.ModLoader;
import net.neoforged.fml.loading.FMLLoader;
import net.neoforged.fml.loading.LoadingModList;
import net.neoforged.fml.startup.StartupArgs;

public final class FmlProbe {
  public static void main(String[] args) throws Exception {
    List<String> program = new ArrayList<>();
    for (String name : new String[]{"mcVersion", "neoForgeVersion", "neoFormVersion"}) {
      String value = System.getProperty("horizon.fml." + name);
      if (value != null) { program.add("--fml." + name); program.add(value); }
    }
    StartupArgs startup = new StartupArgs(Paths.get(System.getProperty("user.dir")), true,
        Dist.DEDICATED_SERVER, true, program.toArray(new String[0]), Set.of(), List.of(),
        ClassLoader.getSystemClassLoader());
    FMLLoader loader = FMLLoader.create(startup);
    LoadingModList list = loader.getLoadingModList();
    System.out.println("mods=" + list.getMods().size());
    for (var mod : list.getMods()) System.out.println("mod=" + mod.getModId());
    ClassLoader game = loader.getGameLayer().findLoader("minecraft");
    Class<?> constants = Class.forName("net.minecraft.SharedConstants", true, game);
    constants.getMethod("tryDetectVersion").invoke(null);
    Class<?> bootstrap = Class.forName("net.minecraft.server.Bootstrap", true, game);
    bootstrap.getMethod("bootStrap").invoke(null);
    ModLoader.gatherAndInitializeMods(Runnable::run, Runnable::run, () -> {});
    System.out.println("initialized");
  }
}
"#;

/// Run the FML probe in a child JVM: FML's game locator assumes an ordinary
/// `java -cp` launch, which an embedded JNI VM does not reproduce.
fn run_real_neoforge(libs: &Path, mods: &[PathBuf]) -> Result<(), String> {
    let classpath = fml_classpath(libs);
    if classpath.is_empty() {
        return Err(format!(
            "{}: no NeoForge unix_args.txt classpath found",
            libs.display()
        ));
    }
    let root = std::env::temp_dir().join(format!(
        "horizon-fml-{}-{}",
        std::process::id(),
        std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .map_or(0, |d| d.as_nanos())
    ));
    let game = root.join("game");
    let mods_dir = game.join("mods");
    fs::create_dir_all(&mods_dir).map_err(|e| format!("{}: {e}", mods_dir.display()))?;
    for mod_jar in mods {
        let name = mod_jar
            .file_name()
            .ok_or_else(|| format!("{}: no file name", mod_jar.display()))?;
        fs::copy(mod_jar, mods_dir.join(name))
            .map_err(|e| format!("{}: {e}", mod_jar.display()))?;
    }
    let source = root.join("FmlProbe.java");
    let classes = root.join("classes");
    fs::create_dir_all(&classes).map_err(|e| format!("{}: {e}", classes.display()))?;
    fs::write(&source, FML_PROBE_SOURCE).map_err(|e| format!("{}: {e}", source.display()))?;
    let javac = std::env::var_os("JAVA_HOME")
        .map(PathBuf::from)
        .map(|home| home.join("bin").join("javac"))
        .unwrap_or_else(|| PathBuf::from("javac"));
    let runtime = std::env::join_paths(&classpath).map_err(|e| e.to_string())?;
    let compiled = Command::new(javac)
        .arg("-cp")
        .arg(&runtime)
        .arg("-d")
        .arg(&classes)
        .arg(&source)
        .output()
        .map_err(|e| format!("javac: {e}"))?;
    if !compiled.status.success() {
        return Err(format!(
            "FML probe did not compile: {}",
            String::from_utf8_lossy(&compiled.stderr)
        ));
    }
    let mut classpath = classpath;
    classpath.push(classes);
    let classpath = std::env::join_paths(&classpath).map_err(|e| e.to_string())?;
    let java = std::env::var_os("JAVA_HOME")
        .map(PathBuf::from)
        .map(|home| home.join("bin").join("java"))
        .unwrap_or_else(|| PathBuf::from("java"));
    let mut command = Command::new(java);
    command
        .current_dir(&game)
        .arg("--add-opens")
        .arg("java.base/java.lang.invoke=ALL-UNNAMED")
        .arg("-Djdk.attach.allowAttachSelf=true")
        .arg(format!("-DlibraryDirectory={}", libs.display()))
        .arg("-cp")
        .arg(&classpath);
    for (name, value) in fml_versions(Some(libs)) {
        command.arg(format!("-Dhorizon.fml.{name}={value}"));
    }
    command.arg("horizon.FmlProbe");
    let output = command
        .output()
        .map_err(|e| format!("could not start Java: {e}"))?;
    let text = format!(
        "{}{}",
        String::from_utf8_lossy(&output.stdout),
        String::from_utf8_lossy(&output.stderr)
    );
    print!("{text}");
    let _ = fs::remove_dir_all(&root);
    if !output.status.success() {
        return Err(format!("FML probe failed ({})", output.status));
    }
    println!("real loader: FML probe completed");
    Ok(())
}

/// The exact runtime classpath an installed NeoForge server's `unix_args.txt`
/// records, resolved against the server directory.
fn fml_classpath(libs: &Path) -> Vec<PathBuf> {
    let mut args = Vec::new();
    let Ok(entries) = fs::read_dir(libs.join("net/neoforged/neoforge")) else {
        return Vec::new();
    };
    for entry in entries.flatten() {
        let path = entry.path().join("unix_args.txt");
        if path.is_file() {
            args.push(path);
        }
    }
    args.sort();
    let Some(path) = args.pop() else {
        return Vec::new();
    };
    let Ok(text) = fs::read_to_string(path) else {
        return Vec::new();
    };
    let Some(index) = text.lines().position(|line| line == "-classpath") else {
        return Vec::new();
    };
    let Some(entries) = text.lines().nth(index + 1) else {
        return Vec::new();
    };
    let server = libs.parent().unwrap_or(libs);
    entries
        .split(if cfg!(windows) { ';' } else { ':' })
        .map(|entry| {
            if Path::new(entry).is_absolute() {
                PathBuf::from(entry)
            } else {
                server.join(entry)
            }
        })
        .filter(|path| path.is_file())
        .collect()
}

/// The `--fml.*` version arguments the installed server records.
fn fml_versions(libs: Option<&Path>) -> Vec<(String, String)> {
    let Some(libs) = libs else {
        return Vec::new();
    };
    let mut args = Vec::new();
    let Ok(entries) = fs::read_dir(libs.join("net/neoforged/neoforge")) else {
        return Vec::new();
    };
    for entry in entries.flatten() {
        let path = entry.path().join("unix_args.txt");
        if path.is_file() {
            args.push(path);
        }
    }
    args.sort();
    let Some(path) = args.pop() else {
        return Vec::new();
    };
    let Ok(text) = fs::read_to_string(path) else {
        return Vec::new();
    };
    text.lines()
        .filter_map(|line| {
            let (key, value) = line.split_once(' ')?;
            key.strip_prefix("--fml.")
                .filter(|name| !name.is_empty() && !value.is_empty())
                .map(|name| (name.to_owned(), value.trim().to_owned()))
        })
        .collect()
}

fn take(args: &mut Vec<String>, name: &str) -> Option<String> {
    let at = args.iter().position(|a| a == name)?;
    if at + 1 >= args.len() {
        return None;
    }
    let value = args.remove(at + 1);
    args.remove(at);
    Some(value)
}

/// Every value of a repeatable flag, in command-line order. A dangling flag is
/// dropped instead of becoming a classpath entry.
fn take_all(args: &mut Vec<String>, name: &str) -> Vec<String> {
    let mut values = Vec::new();
    while let Some(at) = args.iter().position(|a| a == name) {
        if at + 1 >= args.len() {
            args.remove(at);
            break;
        }
        values.push(args.remove(at + 1));
        args.remove(at);
    }
    values
}

/// Finds a Fabric `entrypoints.<kind>` declaration, or NeoForge classes that
/// carry `@Mod`. The runner executes the returned entries in metadata order;
/// callers that need a different environment select it with `--entry-kind`.
fn discover_entries(jar: &Path, kind: &str) -> Result<Vec<String>, String> {
    if let Some((metadata_name, text)) = fabric_metadata_text(jar)? {
        // Datagen has its own group and never falls back to `main`/`client`:
        // only the datagen keys are read, so another group's adapter is never
        // validated for this run.
        if is_datagen_kind(kind) {
            let mut out = Vec::new();
            for key in DATAGEN_ENTRYPOINT_KINDS {
                out.extend(
                    entrypoints_from_metadata(metadata_name, &text, Some(key))?
                        .into_iter()
                        .map(|entry| entry.value),
                );
            }
            return Ok(out);
        }
        let metadata_kind = quilt_entrypoint_kind(metadata_name, kind);
        return entrypoints_from_metadata(metadata_name, &text, Some(metadata_kind))
            .map(|entries| entries.into_iter().map(|entry| entry.value).collect());
    }
    // NeoForge has no Fabric datagen callback, so its `@Mod` classes must not
    // masquerade as datagen entrypoints.
    if is_datagen_kind(kind) {
        return Ok(Vec::new());
    }
    neoforge_mod_classes(jar)
}

/// The Fabric/Quilt metadata file a jar carries, if any. Quilt is checked
/// second because a jar built for both uses the Fabric keys.
fn fabric_metadata_text(jar: &Path) -> Result<Option<(&'static str, String)>, String> {
    let file = File::open(jar).map_err(|e| format!("{}: {e}", jar.display()))?;
    let mut archive = zip::ZipArchive::new(file).map_err(|e| format!("{}: {e}", jar.display()))?;
    let Some(metadata_name) = metadata_file_name(&mut archive) else {
        return Ok(None);
    };
    let mut metadata = archive
        .by_name(metadata_name)
        .map_err(|e| format!("{}: {metadata_name}: {e}", jar.display()))?;
    let mut text = String::new();
    std::io::Read::read_to_string(&mut metadata, &mut text)
        .map_err(|e| format!("{}: {metadata_name}: {e}", jar.display()))?;
    Ok(Some((metadata_name, text)))
}

fn metadata_file_name(archive: &mut zip::ZipArchive<File>) -> Option<&'static str> {
    ["fabric.mod.json", "quilt.mod.json"]
        .into_iter()
        .find(|name| archive.by_name(name).is_ok())
}

/// The metadata path `discover_entries` reads, for wrong-side diagnostics.
fn metadata_path(jar: &Path) -> Result<Option<&'static str>, String> {
    Ok(fabric_metadata_text(jar)?.map(|(metadata_name, _)| metadata_name))
}

/// `@Mod`-annotated top-level classes, in sorted order. NeoForge's
/// `neoforge.mods.toml` does not name its mod class, so this stays a scan.
fn neoforge_mod_classes(jar: &Path) -> Result<Vec<String>, String> {
    let file = File::open(jar).map_err(|e| format!("{}: {e}", jar.display()))?;
    let mut archive = zip::ZipArchive::new(file).map_err(|e| format!("{}: {e}", jar.display()))?;
    let mut out = Vec::new();
    for index in 0..archive.len() {
        let mut entry = archive
            .by_index(index)
            .map_err(|e| format!("{}: reading zip entry: {e}", jar.display()))?;
        let name = entry.name().to_owned();
        if !name.ends_with(".class") || name.contains('$') {
            continue;
        }
        let mut bytes = Vec::new();
        std::io::Read::read_to_end(&mut entry, &mut bytes)
            .map_err(|e| format!("{}: {name}: {e}", jar.display()))?;
        if bytes
            .windows(b"Lnet/neoforged/fml/common/Mod;".len())
            .any(|window| window == b"Lnet/neoforged/fml/common/Mod;")
            || bytes
                .windows(b"Lnet/minecraftforge/fml/common/Mod;".len())
                .any(|window| window == b"Lnet/minecraftforge/fml/common/Mod;")
        {
            out.push(name.trim_end_matches(".class").replace('/', "."));
        }
    }
    out.sort();
    Ok(out)
}

fn quilt_entrypoint_kind<'a>(metadata_name: &str, kind: &'a str) -> &'a str {
    if metadata_name != "quilt.mod.json" {
        return kind;
    }
    match kind {
        "main" => "init",
        "client" => "client_init",
        "server" => "server_init",
        other => other,
    }
}

/// Lists the entrypoint keys declared by a jar for a useful wrong-side error.
/// NeoForge has no metadata list, so an annotated class is represented by the
/// single `neoforge` kind after the bounded class scan.
fn declared_entrypoint_kinds(jar: &Path) -> Result<Vec<String>, String> {
    let file = File::open(jar).map_err(|e| format!("{}: {e}", jar.display()))?;
    let mut archive = zip::ZipArchive::new(file).map_err(|e| format!("{}: {e}", jar.display()))?;
    for metadata_name in ["fabric.mod.json", "quilt.mod.json"] {
        let Ok(mut metadata) = archive.by_name(metadata_name) else {
            continue;
        };
        let mut text = String::new();
        std::io::Read::read_to_string(&mut metadata, &mut text)
            .map_err(|e| format!("{}: {metadata_name}: {e}", jar.display()))?;
        let value: serde_json::Value = serde_json::from_str(&text)
            .map_err(|e| format!("{}: {metadata_name}: {e}", jar.display()))?;
        let mut kinds = value
            .get("entrypoints")
            .and_then(serde_json::Value::as_object)
            .map(|groups| groups.keys().cloned().collect::<Vec<_>>())
            .unwrap_or_default();
        kinds.sort();
        return Ok(kinds);
    }
    let has_neoforge = (0..archive.len()).any(|index| {
        let Ok(mut entry) = archive.by_index(index) else {
            return false;
        };
        let name = entry.name().to_owned();
        if !name.ends_with(".class") || name.contains('$') {
            return false;
        }
        let mut bytes = Vec::new();
        std::io::Read::read_to_end(&mut entry, &mut bytes).is_ok()
            && (bytes
                .windows(b"Lnet/neoforged/fml/common/Mod;".len())
                .any(|window| window == b"Lnet/neoforged/fml/common/Mod;")
                || bytes
                    .windows(b"Lnet/minecraftforge/fml/common/Mod;".len())
                    .any(|window| window == b"Lnet/minecraftforge/fml/common/Mod;"))
    });
    Ok(if has_neoforge {
        vec!["neoforge".to_owned()]
    } else {
        Vec::new()
    })
}

/// One `entrypoints.<kind>` declaration with the adapter Fabric would use.
#[derive(Debug, Clone, PartialEq, Eq)]
struct Entrypoint {
    kind: String,
    value: String,
    adapter: String,
}

/// Adapters whose declarations the static/constructor dispatch can reach.
/// Anything else needs a language adapter this runner does not ship, so
/// discovery rejects it before a JVM starts instead of failing in clinit.
const KNOWN_ENTRYPOINT_ADAPTERS: [&str; 2] = ["default", "kotlin"];

/// Class names for one lifecycle kind, in metadata order. Runtime discovery
/// reads [`entrypoints_from_metadata`] so adapters are validated first; this
/// class-only view stays as the shape the existing tests assert.
#[cfg(test)]
fn fabric_entries(text: &str, kind: &str) -> Result<Vec<String>, String> {
    entrypoints_from_metadata("fabric.mod.json", text, Some(kind))
        .map(|entries| entries.into_iter().map(|entry| entry.value).collect())
}

/// Fabric and Quilt entry containers may nest strings, `{value, adapter}`
/// objects and arrays in any combination; flattening keeps declaration order.
/// A `None` kind collects every lifecycle key for `--list-entrypoints`.
fn entrypoints_from_metadata(
    metadata_name: &str,
    text: &str,
    kind: Option<&str>,
) -> Result<Vec<Entrypoint>, String> {
    let value: serde_json::Value =
        serde_json::from_str(text).map_err(|e| format!("{metadata_name}: {e}"))?;
    let Some(groups) = value
        .get("entrypoints")
        .and_then(serde_json::Value::as_object)
    else {
        return Ok(Vec::new());
    };
    let mut out = Vec::new();
    for (group_kind, group) in groups {
        if kind.is_none_or(|kind| kind == group_kind) {
            flatten_entrypoint(metadata_name, group_kind, group, &mut out)?;
        }
    }
    Ok(out)
}

fn flatten_entrypoint(
    metadata_name: &str,
    kind: &str,
    value: &serde_json::Value,
    out: &mut Vec<Entrypoint>,
) -> Result<(), String> {
    match value {
        serde_json::Value::Array(values) => {
            for value in values {
                flatten_entrypoint(metadata_name, kind, value, out)?;
            }
        }
        serde_json::Value::String(class) => push_entrypoint(kind, class, "default", out),
        serde_json::Value::Object(object) => {
            let adapter = object
                .get("adapter")
                .and_then(serde_json::Value::as_str)
                .unwrap_or("default");
            let class = object
                .get("value")
                .and_then(serde_json::Value::as_str)
                .unwrap_or("");
            if !KNOWN_ENTRYPOINT_ADAPTERS.contains(&adapter) {
                return Err(format!(
                    "{metadata_name}: entrypoint {} declares unsupported adapter {adapter:?}; expected one of {}",
                    if class.is_empty() {
                        "(missing value)"
                    } else {
                        class
                    },
                    KNOWN_ENTRYPOINT_ADAPTERS.join(", ")
                ));
            }
            push_entrypoint(kind, class, adapter, out);
        }
        _ => {}
    }
    Ok(())
}

fn push_entrypoint(kind: &str, value: &str, adapter: &str, out: &mut Vec<Entrypoint>) {
    if value.is_empty() {
        return;
    }
    out.push(Entrypoint {
        kind: kind.to_owned(),
        value: value.to_owned(),
        adapter: adapter.to_owned(),
    });
}

/// Every declaration in one jar, for `--list-entrypoints`.
fn all_entrypoints(jar: &Path) -> Result<Vec<Entrypoint>, String> {
    let Some((metadata_name, text)) = fabric_metadata_text(jar)? else {
        return Ok(neoforge_mod_classes(jar)?
            .into_iter()
            .map(|value| Entrypoint {
                kind: "neoforge".to_owned(),
                value,
                adapter: "default".to_owned(),
            })
            .collect());
    };
    entrypoints_from_metadata(metadata_name, &text, None)
}

/// One `kind<TAB>entrypoint` line per declaration. The sort is stable, so
/// declarations of one kind keep metadata order (including across jars).
fn format_entrypoints(entries: &[Entrypoint]) -> String {
    let mut sorted: Vec<&Entrypoint> = entries.iter().collect();
    sorted.sort_by(|a, b| a.kind.cmp(&b.kind));
    sorted
        .iter()
        .map(|entry| format!("{}\t{}\n", entry.kind, entry.value))
        .collect()
}

fn list_entrypoints(jars: &[String]) -> Result<(), String> {
    let mut entries = Vec::new();
    for jar in jars {
        let path = Path::new(jar);
        entries.extend(all_entrypoints(path)?);
        if metadata_path(path)?.is_none() {
            report_neoforge_metadata(path);
        }
    }
    print!("{}", format_entrypoints(&entries));
    Ok(())
}

/// The wrong-side error is most useful when it names the metadata it read and
/// the side the jar was actually built for.
fn missing_entry_message(
    jar: &str,
    kind: &str,
    metadata: Option<&str>,
    declared: &[String],
) -> String {
    let metadata = metadata.map_or_else(String::new, |name| format!(" ({name})"));
    let declared_note = if declared.is_empty() {
        String::new()
    } else {
        format!("; declared kinds: {}", declared.join(", "))
    };
    let client_only = kind != "client"
        && !declared.is_empty()
        && declared
            .iter()
            .all(|declared_kind| matches!(declared_kind.as_str(), "client" | "client_init"));
    let hint = if client_only {
        "; this jar declares client entrypoints only, so select --entry-kind client (or pass --entry <class>)"
    } else {
        "; pass --entry <class>"
    };
    format!("no {kind} entrypoint found in {jar}{metadata}{declared_note}{hint}")
}

/// NeoForge's `mods.toml` carries loader, mod id and mixin markers but no mod
/// class. These fields are diagnostics only: the `@Mod` class scan decides
/// what runs, keeping NeoForge constructor-only semantics.
#[derive(Debug, Default, PartialEq, Eq)]
struct NeoForgeMetadata {
    path: Option<String>,
    mod_loader: Option<String>,
    mod_ids: Vec<String>,
    jar_jars: usize,
    /// `[[mixins]] config` with the `environment` its block declares, if any.
    mixin_configs: Vec<(String, MixinEnvironment)>,
}

impl NeoForgeMetadata {
    fn diagnostic(&self) -> Option<String> {
        let mut parts = Vec::new();
        if let Some(loader) = &self.mod_loader {
            parts.push(format!("modLoader {loader}"));
        }
        if !self.mod_ids.is_empty() {
            parts.push(format!("mod ids {}", self.mod_ids.join(", ")));
        }
        if self.jar_jars > 0 {
            parts.push(format!("{} nested jarJar jar(s)", self.jar_jars));
        }
        if !self.mixin_configs.is_empty() {
            parts.push(format!("{} mixin config(s)", self.mixin_configs.len()));
        }
        (!parts.is_empty()).then(|| {
            format!(
                "{} (diagnostics only): {}",
                self.path.as_deref().unwrap_or("NeoForge metadata"),
                parts.join("; ")
            )
        })
    }
}

/// Hand parser: only the top-level `modLoader`, `[[mods]] modId` and
/// `[[mixins]] config`/`environment` keys matter, and no TOML dependency is
/// worth adding.
fn parse_neoforge_toml(text: &str) -> NeoForgeMetadata {
    let mut metadata = NeoForgeMetadata::default();
    let mut section = String::new();
    // The `[[mixins]]` block in progress. `environment` may come before or
    // after its `config`, so the pair is flushed when the block ends.
    let mut mixin_config: Option<String> = None;
    let mut mixin_environment = MixinEnvironment::Both;
    for raw in text.lines() {
        let line = raw.split('#').next().unwrap_or("").trim();
        if line.starts_with('[') {
            flush_mixin_block(&mut metadata, &mut mixin_config, &mut mixin_environment);
            section = line.to_owned();
            continue;
        }
        let Some((key, value)) = line.split_once('=') else {
            continue;
        };
        let value = value.trim().trim_matches(|c| c == '"' || c == '\'');
        if value.is_empty() {
            continue;
        }
        match (section.as_str(), key.trim()) {
            ("", "modLoader") => metadata.mod_loader = Some(value.to_owned()),
            ("[[mods]]", "modId") => push_unique(&mut metadata.mod_ids, value),
            ("[[mixins]]", "config") => mixin_config = Some(value.to_owned()),
            ("[[mixins]]", "environment") => mixin_environment = MixinEnvironment::parse(value),
            _ => {}
        }
    }
    flush_mixin_block(&mut metadata, &mut mixin_config, &mut mixin_environment);
    metadata
}

/// Commit one parsed `[[mixins]]` block and reset the next block's state.
fn flush_mixin_block(
    metadata: &mut NeoForgeMetadata,
    mixin_config: &mut Option<String>,
    mixin_environment: &mut MixinEnvironment,
) {
    if let Some(config) = mixin_config.take() {
        push_mixin_config(&mut metadata.mixin_configs, &config, *mixin_environment);
    }
    *mixin_environment = MixinEnvironment::Both;
}

fn neoforge_metadata(jar: &Path) -> Result<NeoForgeMetadata, String> {
    let file = File::open(jar).map_err(|e| format!("{}: {e}", jar.display()))?;
    let mut archive = zip::ZipArchive::new(file).map_err(|e| format!("{}: {e}", jar.display()))?;
    let mut metadata = NeoForgeMetadata::default();
    for name in ["META-INF/neoforge.mods.toml", "META-INF/mods.toml"] {
        let Ok(mut entry) = archive.by_name(name) else {
            continue;
        };
        let mut text = String::new();
        std::io::Read::read_to_string(&mut entry, &mut text)
            .map_err(|e| format!("{}: {name}: {e}", jar.display()))?;
        metadata = parse_neoforge_toml(&text);
        metadata.path = Some(name.to_owned());
        break;
    }
    for index in 0..archive.len() {
        let Ok(entry) = archive.by_index(index) else {
            continue;
        };
        let name = entry.name().to_owned();
        if let Some(nested) = name.strip_prefix("META-INF/jarjar/") {
            if nested.ends_with(".jar") {
                metadata.jar_jars += 1;
            }
        } else if is_mixin_config_name(&name) {
            push_root_mixin_config(&mut metadata.mixin_configs, &name);
        }
    }
    Ok(metadata)
}

fn is_mixin_config_name(name: &str) -> bool {
    name.ends_with(".mixins.json") || (!name.contains('/') && name.contains("mixins"))
}

fn push_unique(values: &mut Vec<String>, value: &str) {
    if !values.iter().any(|existing| existing == value) {
        values.push(value.to_owned());
    }
}

/// The side a mixin config was declared for. Fabric and Quilt spell `*` for
/// "both", and a declaration with no environment at all means the same thing.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum MixinEnvironment {
    Client,
    Server,
    /// `*`, an unknown value, or no environment declared: both sides.
    Both,
}

impl MixinEnvironment {
    /// A declared environment. Unknown values stay on both sides instead of
    /// dropping a config the loader would still load.
    fn parse(declared: &str) -> Self {
        match declared.trim().to_ascii_lowercase().as_str() {
            "client" => Self::Client,
            "server" => Self::Server,
            _ => Self::Both,
        }
    }

    /// The environment `--entry-kind` selects. Loader-lifecycle kinds
    /// (`main`, `preLaunch`, `neoforge`, `init`) can run on either side.
    fn selected(entry_kind: &str) -> Self {
        match entry_kind {
            "client" | "client_init" => Self::Client,
            "server" | "server_init" => Self::Server,
            _ => Self::Both,
        }
    }

    /// Whether a config declared for `self` is registered on `selected`. A
    /// `*` selection takes everything, and an undeclared config loads
    /// everywhere.
    fn matches(self, selected: Self) -> bool {
        selected == Self::Both || self == Self::Both || self == selected
    }

    /// The `--list-mixin-configs` column and skipped-line spelling.
    fn label(self) -> &'static str {
        match self {
            Self::Client => "client",
            Self::Server => "server",
            Self::Both => "*",
        }
    }

    /// Two declarations of one file merge permissively: `*` wins, and a
    /// client+server pair is both sides.
    fn broadest(self, other: Self) -> Self {
        if self == other { self } else { Self::Both }
    }
}

/// Adds a declared config, folding a second declaration of the same file into
/// the broader environment. Declaration order is kept; callers sort.
fn push_mixin_config(
    configs: &mut Vec<(String, MixinEnvironment)>,
    config: &str,
    environment: MixinEnvironment,
) {
    if config.is_empty() {
        return;
    }
    match configs.iter_mut().find(|(declared, _)| declared == config) {
        Some((_, existing)) => *existing = existing.broadest(environment),
        None => configs.push((config.to_owned(), environment)),
    }
}

/// A config the root `*.mixins.json` scan found. It declares no environment,
/// and being on the jar root must not widen one a metadata declaration already
/// gave this file.
fn push_root_mixin_config(configs: &mut Vec<(String, MixinEnvironment)>, config: &str) {
    if config.is_empty() || configs.iter().any(|(declared, _)| declared == config) {
        return;
    }
    configs.push((config.to_owned(), MixinEnvironment::Both));
}

/// One mixin config a jar declares, or one passed with `--mixin-config`.
#[derive(Debug, Clone, PartialEq, Eq)]
struct MixinConfigRef {
    /// The archive the config lives in. For `--mixin-config`, the file itself.
    source: PathBuf,
    /// The zip entry name, or the path as typed for `--mixin-config`.
    config: String,
    /// The side the declaration named; `*` when it named none.
    environment: MixinEnvironment,
    explicit: bool,
}

impl MixinConfigRef {
    /// The first column of `--list-mixin-configs`: `-` for a config passed on
    /// the command line, which no jar owns.
    fn jar_label(&self) -> String {
        if self.explicit {
            "-".to_owned()
        } else {
            self.source.display().to_string()
        }
    }

    /// The config text, capped so a hostile archive cannot make the probe read
    /// without bound. Failure labels are stable so diagnostics do not vary by
    /// host.
    fn read(&self) -> Result<String, &'static str> {
        const MAX_MIXIN_CONFIG_BYTES: u64 = 1 << 20;
        if self.explicit {
            let size = fs::metadata(&self.source).map_err(|_| "not found")?.len();
            if size > MAX_MIXIN_CONFIG_BYTES {
                return Err("too large");
            }
            return fs::read_to_string(&self.source).map_err(|_| "unreadable");
        }
        let file = File::open(&self.source).map_err(|_| "jar unreadable")?;
        let mut archive = zip::ZipArchive::new(file).map_err(|_| "jar unreadable")?;
        let mut entry = archive
            .by_name(&self.config)
            .map_err(|_| "missing from the jar")?;
        if entry.size() > MAX_MIXIN_CONFIG_BYTES {
            return Err("too large");
        }
        let mut text = String::new();
        std::io::Read::read_to_string(&mut entry, &mut text).map_err(|_| "unreadable")?;
        Ok(text)
    }

    /// Whether the archive (or the explicit file) really carries the config.
    /// Chosen over [`Self::read`] so a config above the probe's read bound is
    /// still handed to Mixin, which has its own limits.
    fn exists(&self) -> bool {
        if self.explicit {
            return fs::metadata(&self.source).is_ok_and(|meta| meta.is_file());
        }
        let Ok(file) = File::open(&self.source) else {
            return false;
        };
        let Ok(mut archive) = zip::ZipArchive::new(file) else {
            return false;
        };
        archive.by_name(&self.config).is_ok()
    }
}

/// Mixin configs for every jar on the classpath plus the explicit
/// `--mixin-config` files, deduplicated and sorted. Only archive entries are
/// read, so discovery never follows a path out of a supplied jar.
fn discover_mixin_configs(classpath: &[PathBuf], explicit: &[String]) -> Vec<MixinConfigRef> {
    const MAX_CONFIGS: usize = 256;
    let mut out: Vec<MixinConfigRef> = explicit
        .iter()
        .map(|path| MixinConfigRef {
            source: PathBuf::from(path),
            config: path.clone(),
            // An explicit config names no side, so it loads on both.
            environment: MixinEnvironment::Both,
            explicit: true,
        })
        .collect();
    for path in classpath {
        let Some(configs) = jar_mixin_configs(path) else {
            continue;
        };
        out.extend(
            configs
                .into_iter()
                .map(|(config, environment)| MixinConfigRef {
                    source: path.clone(),
                    config,
                    environment,
                    explicit: false,
                }),
        );
    }
    out.sort_by(|a, b| (a.jar_label(), &a.config).cmp(&(b.jar_label(), &b.config)));
    out.dedup();
    if out.len() > MAX_CONFIGS {
        out.truncate(MAX_CONFIGS);
        eprintln!("horizon-jvm: mixin config discovery capped at {MAX_CONFIGS} configs");
    }
    out
}

/// The mixin configs a jar declares or carries at its root: Fabric/Quilt
/// metadata entries, NeoForge `[[mixins]] config`, and root `*.mixins.json`
/// (the last two with no environment, so `*`).
fn jar_mixin_configs(jar: &Path) -> Option<Vec<(String, MixinEnvironment)>> {
    let file = File::open(jar).ok()?;
    let mut archive = zip::ZipArchive::new(file).ok()?;
    let mut configs = Vec::new();
    if let Some(value) = archive_json(&mut archive, "fabric.mod.json") {
        extend_mixin_configs(&mut configs, fabric_mixin_configs(&value));
    }
    if let Some(value) = archive_json(&mut archive, "quilt.mod.json") {
        extend_mixin_configs(&mut configs, quilt_mixin_configs(&value));
    }
    for name in ["META-INF/neoforge.mods.toml", "META-INF/mods.toml"] {
        let Ok(mut entry) = archive.by_name(name) else {
            continue;
        };
        let mut text = String::new();
        if std::io::Read::read_to_string(&mut entry, &mut text).is_ok() {
            extend_mixin_configs(&mut configs, parse_neoforge_toml(&text).mixin_configs);
        }
        break;
    }
    for index in 0..archive.len() {
        let Ok(entry) = archive.by_index(index) else {
            continue;
        };
        let name = entry.name().to_owned();
        if !name.contains('/') && name.ends_with(".mixins.json") {
            push_root_mixin_config(&mut configs, &name);
        }
    }
    configs.retain(|(config, _)| !config.is_empty());
    configs.sort_by(|a, b| a.0.cmp(&b.0));
    Some(configs)
}

/// One metadata file parsed as JSON. Discovery is best-effort: a jar without
/// the file, or with unreadable JSON in it, contributes no declarations.
fn archive_json(archive: &mut zip::ZipArchive<File>, name: &str) -> Option<serde_json::Value> {
    let mut entry = archive.by_name(name).ok()?;
    let mut text = String::new();
    std::io::Read::read_to_string(&mut entry, &mut text).ok()?;
    serde_json::from_str(&text).ok()
}

fn extend_mixin_configs(
    out: &mut Vec<(String, MixinEnvironment)>,
    configs: Vec<(String, MixinEnvironment)>,
) {
    for (config, environment) in configs {
        push_mixin_config(out, &config, environment);
    }
}

/// Fabric's `mixins` list: classpath strings, or `{config, environment}`
/// objects. A bare string is accepted for hand-written metadata and has no
/// environment, so it loads on either side.
fn fabric_mixin_configs(value: &serde_json::Value) -> Vec<(String, MixinEnvironment)> {
    value
        .get("mixins")
        .map_or_else(Vec::new, mixin_declarations)
}

/// Quilt's `mixin` key: one config path or a list of them, plus the same
/// `{mixin, environment}` object form Fabric uses.
fn quilt_mixin_configs(value: &serde_json::Value) -> Vec<(String, MixinEnvironment)> {
    value.get("mixin").map_or_else(Vec::new, mixin_declarations)
}

/// A declaration list whose elements are strings or `{config|mixin,
/// environment}` objects, in declaration order.
fn mixin_declarations(value: &serde_json::Value) -> Vec<(String, MixinEnvironment)> {
    let mut out = Vec::new();
    for value in json_values(value) {
        match value {
            serde_json::Value::String(config) => {
                push_mixin_config(&mut out, config, MixinEnvironment::Both);
            }
            serde_json::Value::Object(object) => {
                let config = object
                    .get("config")
                    .or_else(|| object.get("mixin"))
                    .and_then(serde_json::Value::as_str)
                    .unwrap_or("");
                let environment = object
                    .get("environment")
                    .and_then(serde_json::Value::as_str)
                    .map_or(MixinEnvironment::Both, MixinEnvironment::parse);
                push_mixin_config(&mut out, config, environment);
            }
            _ => {}
        }
    }
    out
}

/// A JSON list, or a single value where a list was expected.
fn json_values(value: &serde_json::Value) -> Vec<&serde_json::Value> {
    match value {
        serde_json::Value::Array(items) => items.iter().collect(),
        other => vec![other],
    }
}

/// The bounded view of a mixin config the fallback reports: `package`,
/// `mixins`, `client`, `server`, `required` and `priority`.
#[derive(Debug, Default, PartialEq, Eq)]
struct MixinConfig {
    /// Fully-qualified mixin classes, in config order.
    entries: Vec<String>,
    /// Entries Mixin would treat as required.
    required: usize,
    priority: Option<i64>,
}

/// Tolerant reader: a config whose lists hold something other than class names
/// still reports what it can instead of failing the run. `required` defaults to
/// true, as in Mixin.
fn parse_mixin_config(text: &str) -> Result<MixinConfig, String> {
    let value: serde_json::Value = serde_json::from_str(text).map_err(|e| e.to_string())?;
    let object = value
        .as_object()
        .ok_or_else(|| "not a JSON object".to_owned())?;
    let package = object
        .get("package")
        .and_then(serde_json::Value::as_str)
        .filter(|package| !package.is_empty());
    let required = object
        .get("required")
        .and_then(serde_json::Value::as_bool)
        .unwrap_or(true);
    let mut config = MixinConfig {
        entries: Vec::new(),
        required: 0,
        priority: object.get("priority").and_then(serde_json::Value::as_i64),
    };
    for key in ["mixins", "client", "server"] {
        for (name, entry_required) in mixin_entries(object.get(key)) {
            config.entries.push(match package {
                Some(package) if !name.contains('.') => format!("{package}.{name}"),
                _ => name,
            });
            if entry_required.unwrap_or(required) {
                config.required += 1;
            }
        }
    }
    Ok(config)
}

/// `mixins`/`client`/`server` members as `(class, per-entry required)` pairs.
/// Elements may be strings or `{mixin, target, required}` objects.
fn mixin_entries(value: Option<&serde_json::Value>) -> Vec<(String, Option<bool>)> {
    let Some(value) = value else {
        return Vec::new();
    };
    json_values(value)
        .into_iter()
        .filter_map(|value| match value {
            serde_json::Value::String(name) => Some((name.clone(), None)),
            serde_json::Value::Object(object) => {
                let name = object
                    .get("mixin")
                    .or_else(|| object.get("target"))
                    .and_then(serde_json::Value::as_str)?;
                let required = object.get("required").and_then(serde_json::Value::as_bool);
                Some((name.to_owned(), required))
            }
            _ => None,
        })
        .filter(|(name, _)| !name.is_empty())
        .collect()
}

/// `mixin config:` and `mixin targets:` for one config, plus the priority that
/// orders it. The targets list names the classes the config registers for
/// weaving, package-qualified; what they target lives in their `@Mixin`
/// annotations, which this probe does not read.
fn mixin_config_report(reference: &MixinConfigRef) -> (Option<i64>, Vec<String>) {
    let text = match reference.read() {
        Ok(text) => text,
        Err(reason) => {
            let line = format!("mixin config: {} ({reason})", reference.config);
            return (None, vec![line]);
        }
    };
    match parse_mixin_config(&text) {
        Ok(config) => {
            let mut lines = vec![format!(
                "mixin config: {} ({} mixins, {} required)",
                reference.config,
                config.entries.len(),
                config.required
            )];
            if !config.entries.is_empty() {
                lines.push(format!("mixin targets: {}", config.entries.join(", ")));
            }
            (config.priority, lines)
        }
        Err(reason) => (
            None,
            vec![format!(
                "mixin config: {} (invalid JSON: {reason})",
                reference.config
            )],
        ),
    }
}

/// Every report line, ordered by Mixin's priority and then the diagnostic text
/// so the output does not depend on classpath enumeration. Identical lines are
/// folded: a config two jars both declare as missing (or both carry) is named
/// once.
fn report_mixin_configs(configs: &[MixinConfigRef]) -> Vec<String> {
    let mut reports: Vec<(Option<i64>, Vec<String>)> =
        configs.iter().map(mixin_config_report).collect();
    reports.sort_by(|a, b| {
        a.0.unwrap_or(i64::MIN)
            .cmp(&b.0.unwrap_or(i64::MIN))
            .then_with(|| a.1.cmp(&b.1))
    });
    let mut lines: Vec<String> = reports.into_iter().flat_map(|(_, lines)| lines).collect();
    lines.dedup();
    lines
}

/// Upper bound for one `-Dmixin.configs` value. Mixin reads a single property,
/// so a hostile archive must not be able to grow the JVM argument without
/// bound.
const MAX_MIXIN_CONFIG_PROPERTY_BYTES: usize = 8192;

/// The value of `-Dmixin.configs`: Mixin's comma-separated classpath resource
/// list. Names are sorted and deduplicated so the value never depends on
/// classpath enumeration, and the list stops at
/// [`MAX_MIXIN_CONFIG_PROPERTY_BYTES`]. Empty names and names containing a
/// comma are dropped because the property has no way to express them.
fn format_mixin_config_property(names: impl IntoIterator<Item = String>) -> Option<String> {
    let mut names: Vec<String> = names
        .into_iter()
        .filter(|name| !name.is_empty() && !name.contains(','))
        .collect();
    names.sort();
    names.dedup();
    let mut value = String::new();
    for name in names {
        let separator = usize::from(!value.is_empty());
        if value.len() + separator + name.len() > MAX_MIXIN_CONFIG_PROPERTY_BYTES {
            break;
        }
        if separator == 1 {
            value.push(',');
        }
        value.push_str(&name);
    }
    (!value.is_empty()).then_some(value)
}

/// The property for the discovered configs, or `None` when no supplied jar
/// carries one. Config names come from archive entries or `--mixin-config`
/// values only, so the list cannot name a path outside them.
///
/// Fabric Loader's own hand-off is different: `FabricMixinBootstrap` reads each
/// mod's *parsed* metadata and calls `Mixins.addConfiguration`. The embedded
/// bridge seeds container proxies rather than parsed metadata, so the probe
/// registers this same list itself after the static bootstrap
/// ([`register_mixin_configs`]); the legacy property stays set for Mixin builds
/// that read it at launch. A real weaving run still needs the loader to agree on
/// the list.
fn mixin_config_property(configs: &[MixinConfigRef]) -> Option<String> {
    format_mixin_config_property(
        configs
            .iter()
            .filter(|config| config.exists())
            .map(|config| config.config.clone()),
    )
}

/// The configs the selected environment registers: everything for `*`, and
/// the `*`-plus-own-side declarations for one side. The property and the
/// `addConfiguration` calls both walk this list, so filtering happens once.
fn select_mixin_configs(
    configs: Vec<MixinConfigRef>,
    selected: MixinEnvironment,
) -> Vec<MixinConfigRef> {
    configs
        .into_iter()
        .filter(|config| config.environment.matches(selected))
        .collect()
}

/// One `mixin configs: skipped <environment> <config>` line per config the
/// selected environment leaves out. Sorted and folded, so a config two jars
/// declare is named once and the order never depends on the classpath.
fn skipped_mixin_configs(configs: &[MixinConfigRef], selected: MixinEnvironment) -> Vec<String> {
    let mut lines: Vec<String> = configs
        .iter()
        .filter(|config| !config.environment.matches(selected))
        .map(|config| {
            format!(
                "mixin configs: skipped {} {}",
                config.environment.label(),
                config.config
            )
        })
        .collect();
    lines.sort();
    lines.dedup();
    lines
}

/// The configs the property carries, in the property's own order. Registration
/// walks this list, so the JVM property and the `addConfiguration` calls cannot
/// drift apart.
fn mixin_config_names(property: Option<&str>) -> Vec<&str> {
    property
        .map(|value| value.split(',').filter(|name| !name.is_empty()).collect())
        .unwrap_or_default()
}

/// How many configs the property carries, for the deterministic log line.
fn mixin_registered_count(property: Option<&str>) -> usize {
    mixin_config_names(property).len()
}

/// `mixin configs: N registered`, or `mixin configs: none` when discovery found
/// nothing a jar actually carries.
fn mixin_configs_line(registered: usize) -> String {
    if registered == 0 {
        "mixin configs: none".to_owned()
    } else {
        format!("mixin configs: {registered} registered")
    }
}

/// The JVM options that hand the config list to Mixin. Kept as an argument list
/// so a test can inspect the exact property without starting a JVM.
fn mixin_jvm_options(property: Option<&str>) -> Vec<String> {
    property
        .map(|value| vec![format!("-Dmixin.configs={value}")])
        .unwrap_or_default()
}

/// `--list-mixin-configs`: one `jar<TAB>config<TAB>environment` line per
/// declaration, sorted. Everything is listed regardless of `--entry-kind`, so
/// the column is how a filtered run's decision can be checked. No JVM starts,
/// and only the jars named on the command line are scanned (nested jars are a
/// classpath-time expansion).
fn list_mixin_configs(jars: &[String], explicit: &[String]) -> Result<(), String> {
    let classpath: Vec<PathBuf> = jars.iter().map(PathBuf::from).collect();
    let configs = discover_mixin_configs(&classpath, explicit);
    print!("{}", format_mixin_configs(&configs));
    Ok(())
}

fn format_mixin_configs(configs: &[MixinConfigRef]) -> String {
    let mut lines: Vec<String> = configs
        .iter()
        .map(|config| {
            format!(
                "{}\t{}\t{}",
                config.jar_label(),
                config.config,
                config.environment.label()
            )
        })
        .collect();
    lines.sort();
    lines.dedup();
    lines.into_iter().map(|line| line + "\n").collect()
}

/// The static bootstrap's outcome: `Ok(())` means Mixin came up far enough to
/// accept `addConfiguration`; `Err` is the fallback label for the reported
/// failure. A failure leaves the property hand-off in place and skips
/// registration, which is only meaningful after a successful bootstrap.
type MixinBootstrap = Result<(), String>;

/// One step of the Mixin hand-off between the config report and the first
/// entrypoint, in Fabric's order. The plan is data, so a test can assert the
/// sequence without starting a JVM.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum MixinStage {
    /// `MixinBootstrap.init()`, reported as `mixin bootstrap: <label>`.
    Bootstrap,
    /// `Mixins.addConfiguration(name)` per config, reported per failure plus a
    /// final summary.
    Registration,
}

/// The stages a run with `registered` configs performs, in order. A run with
/// none has no stage: it reports `mixin bootstrap: no configs` and loads no
/// Mixin class for nothing. Registration always follows the bootstrap that
/// makes it meaningful.
fn mixin_stages(registered: usize) -> &'static [MixinStage] {
    if registered == 0 {
        &[]
    } else {
        &[MixinStage::Bootstrap, MixinStage::Registration]
    }
}

/// The text after `mixin bootstrap:`: `ok`, or the failure's fallback label.
fn mixin_bootstrap_line(outcome: &MixinBootstrap) -> &str {
    outcome.as_ref().err().map_or("ok", String::as_str)
}

/// The two JVM effects registration needs, so the unavailable and
/// partial-failure paths run in a unit test instead of a started JVM.
trait MixinRegistrar {
    /// Whether `org.spongepowered.asm.mixin.Mixins` and its
    /// `addConfiguration(Ljava/lang/String;)V` exist.
    fn available(&mut self) -> bool;

    /// One `addConfiguration` call. Anything thrown is cleared either way;
    /// `Err` carries the label the failure line reports.
    fn add_configuration(&mut self, config: &str) -> Result<(), String>;
}

/// Mixin's public registration API, the same call Fabric's
/// `FabricMixinBootstrap` makes for each mod's parsed metadata.
const MIXINS_CLASS: &str = "org/spongepowered/asm/mixin/Mixins";
const ADD_CONFIGURATION: &str = "addConfiguration";
const ADD_CONFIGURATION_SIG: &str = "(Ljava/lang/String;)V";

/// [`MixinRegistrar`] over JNI. The `Mixins` class is resolved once, when
/// availability is checked, so N configs cost one class lookup and N calls.
struct JniMixinRegistrar<'env, 'local> {
    env: &'env mut JNIEnv<'local>,
    class: Option<JClass<'local>>,
}

impl<'env, 'local> JniMixinRegistrar<'env, 'local> {
    fn new(env: &'env mut JNIEnv<'local>) -> Self {
        Self { env, class: None }
    }
}

impl MixinRegistrar for JniMixinRegistrar<'_, '_> {
    fn available(&mut self) -> bool {
        let Ok(class) = self.env.find_class(MIXINS_CLASS) else {
            let _ = self.env.exception_clear();
            return false;
        };
        // A class without the method is as unavailable as a missing class:
        // keep the property hand-off and let the probe continue.
        if self
            .env
            .get_static_method_id(&class, ADD_CONFIGURATION, ADD_CONFIGURATION_SIG)
            .is_err()
        {
            let _ = self.env.exception_clear();
            return false;
        }
        self.class = Some(class);
        true
    }

    fn add_configuration(&mut self, config: &str) -> Result<(), String> {
        let Some(class) = self.class.as_ref() else {
            return Err("Mixins is not available".to_owned());
        };
        let name = self
            .env
            .new_string(config)
            .map_err(|error| format!("config name: {error}"))?;
        let name = JObject::from(name);
        match self.env.call_static_method(
            class,
            ADD_CONFIGURATION,
            ADD_CONFIGURATION_SIG,
            &[JValue::Object(&name)],
        ) {
            Ok(_) => Ok(()),
            Err(error) => {
                let fallback = (error.to_string() == "Java exception was thrown")
                    .then(|| exception_fallback(self.env))
                    .flatten();
                // One bad config must not poison the next call, and its
                // exception trace would repeat the config list per failure.
                let _ = self.env.exception_clear();
                Err(fallback.unwrap_or_else(|| error.to_string()))
            }
        }
    }
}

/// The registration stage: one `Mixins.addConfiguration` per config the
/// property carries, in the property's order. Pure apart from
/// [`MixinRegistrar`], so the skip, unavailable and partial-failure paths are
/// unit tested without a JVM.
///
/// Diagnostics stay bounded: a failing config gets one `failed` line (its
/// fallback label, never the whole config list), and one summary closes the
/// stage.
fn register_mixin_configs(
    bootstrap: Option<&MixinBootstrap>,
    configs: &[&str],
    registrar: &mut impl MixinRegistrar,
) -> Vec<String> {
    if !bootstrap.is_some_and(|bootstrap| bootstrap.is_ok()) || configs.is_empty() {
        return Vec::new();
    }
    if !registrar.available() {
        return vec!["mixin registration: unavailable".to_owned()];
    }
    let mut lines = Vec::new();
    let mut registered = 0usize;
    for config in configs {
        match registrar.add_configuration(config) {
            Ok(()) => registered += 1,
            Err(label) => lines.push(format!("mixin registration: failed ({label})")),
        }
    }
    lines.push(format!(
        "mixin registration: {registered}/{} registered",
        configs.len()
    ));
    lines
}

/// Mixin's static bootstrap (`MixinBootstrap.init`), the way Fabric's launch
/// handler runs it. Bounded to the classes the classpath already has: a missing
/// runtime or a thrown exception becomes a reported fallback label, never a
/// failed probe.
fn mixin_bootstrap_label(env: &mut JNIEnv) -> MixinBootstrap {
    let class = match env.find_class("org/spongepowered/asm/launch/MixinBootstrap") {
        Ok(class) => class,
        Err(_) => {
            let _ = env.exception_clear();
            return Err(fallback_label(
                "java.lang.ClassNotFoundException",
                Some("org.spongepowered.asm.launch.MixinBootstrap"),
            )
            .unwrap_or_default());
        }
    };
    match env.call_static_method(&class, "init", "()V", &[]) {
        Ok(_) => Ok(()),
        Err(error) => {
            let fallback = (error.to_string() == "Java exception was thrown")
                .then(|| exception_fallback(env))
                .flatten();
            let _ = env.exception_describe();
            let _ = env.exception_clear();
            Err(fallback.unwrap_or_else(|| error.to_string()))
        }
    }
}

/// The `MixinEnvironment$Side` constant a run sets. `None` is Mixin's default,
/// for a loader-lifecycle probe (`main`, `preLaunch`, `neoforge`) that has no game
/// environment to pick a side from.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum MixinSide {
    Client,
    Server,
}

impl MixinSide {
    fn selected(entry_kind: &str) -> Option<Self> {
        match entry_kind {
            "client" | "client_init" => Some(Self::Client),
            "server" | "server_init" => Some(Self::Server),
            _ => None,
        }
    }

    /// The enum's static field, read with `get_static_field`.
    fn field(self) -> &'static str {
        match self {
            Self::Client => "CLIENT",
            Self::Server => "SERVER",
        }
    }

    /// The `mixin phase:` value.
    fn label(self) -> &'static str {
        match self {
            Self::Client => "client",
            Self::Server => "server",
        }
    }
}

/// One step of the hand-off between registration and the first entrypoint.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum MixinPhaseStep {
    /// `MixinBootstrap.onLoadingDone()V`.
    LoadingDone,
    /// `MixinEnvironment.getDefaultEnvironment()`, then its `setSide`.
    Environment,
}

/// The steps a run that reached Mixin performs, in order: `onLoadingDone`, which
/// Fabric calls once the loader registered the configs, then the side, which
/// `setSide` only assigns while it is still `UNKNOWN`.
const MIXIN_PHASE_STEPS: [MixinPhaseStep; 2] =
    [MixinPhaseStep::LoadingDone, MixinPhaseStep::Environment];

/// A step's result. Anything but `Ok` is reported, never fatal.
#[derive(Debug, Clone, PartialEq, Eq)]
enum PhaseOutcome {
    Ok,
    /// The class, method or field is not on the classpath.
    Unavailable,
    /// The call threw; the label is already bounded and exception-free.
    Failed(String),
}

/// The JVM effects the plan needs, so every outcome runs in a unit test instead
/// of a started JVM.
trait MixinPhaseDriver {
    /// `MixinBootstrap.onLoadingDone()V`; Mixin 0.8.7 ships no such method.
    fn loading_done(&mut self) -> PhaseOutcome;

    /// `MixinEnvironment.getDefaultEnvironment()`, then its `setSide` for a sided
    /// run. Resolution stops at the first unavailable step.
    fn set_side(&mut self, side: Option<MixinSide>) -> PhaseOutcome;
}

/// `mixin phase: <step>` with the outcome: `ok`, `unavailable`, or
/// `failed (<label>)`. The environment line carries no `ok`: the side it names is
/// the state a reader wants.
fn mixin_phase_line(
    step: MixinPhaseStep,
    side: Option<MixinSide>,
    outcome: &PhaseOutcome,
) -> String {
    let label = match step {
        MixinPhaseStep::LoadingDone => "loading-done",
        MixinPhaseStep::Environment => side.map_or("default", MixinSide::label),
    };
    match outcome {
        PhaseOutcome::Ok => match step {
            MixinPhaseStep::LoadingDone => format!("mixin phase: {label} ok"),
            MixinPhaseStep::Environment => format!("mixin phase: {label}"),
        },
        PhaseOutcome::Unavailable => format!("mixin phase: {label} unavailable"),
        PhaseOutcome::Failed(reason) => format!("mixin phase: {label} failed ({reason})"),
    }
}

/// The lifecycle stage after registration: one line per step, in
/// [`MIXIN_PHASE_STEPS`] order. Pure apart from [`MixinPhaseDriver`].
fn run_mixin_phase(
    bootstrap: Option<&MixinBootstrap>,
    side: Option<MixinSide>,
    driver: &mut impl MixinPhaseDriver,
) -> Vec<String> {
    if !bootstrap.is_some_and(|bootstrap| bootstrap.is_ok()) {
        return Vec::new();
    }
    MIXIN_PHASE_STEPS
        .iter()
        .map(|step| {
            let outcome = match step {
                MixinPhaseStep::LoadingDone => driver.loading_done(),
                MixinPhaseStep::Environment => driver.set_side(side),
            };
            mixin_phase_line(*step, side, &outcome)
        })
        .collect()
}

const MIXIN_BOOTSTRAP_CLASS: &str = "org/spongepowered/asm/launch/MixinBootstrap";
const MIXIN_ON_LOADING_DONE: &str = "onLoadingDone";
const MIXIN_ENVIRONMENT_CLASS: &str = "org/spongepowered/asm/mixin/MixinEnvironment";
const MIXIN_SIDE_CLASS: &str = "org/spongepowered/asm/mixin/MixinEnvironment$Side";
const MIXIN_SIDE_SIG: &str = "Lorg/spongepowered/asm/mixin/MixinEnvironment$Side;";
const MIXIN_GET_DEFAULT_ENVIRONMENT: &str = "getDefaultEnvironment";
const MIXIN_GET_DEFAULT_ENVIRONMENT_SIG: &str = "()Lorg/spongepowered/asm/mixin/MixinEnvironment;";
const MIXIN_SET_ACTIVE_ENVIRONMENT: &str = "setActiveEnvironment";
const MIXIN_SET_ACTIVE_ENVIRONMENT_SIG: &str = "(Lorg/spongepowered/asm/mixin/MixinEnvironment;)V";
const MIXIN_SET_SIDE: &str = "setSide";
const MIXIN_SET_SIDE_SIG: &str = "(Lorg/spongepowered/asm/mixin/MixinEnvironment$Side;)Lorg/spongepowered/asm/mixin/MixinEnvironment;";

/// [`MixinPhaseDriver`] over JNI. Every member is reflective, so a Mixin build
/// without one of them reports `unavailable` instead of failing.
struct JniMixinPhase<'env, 'local> {
    env: &'env mut JNIEnv<'local>,
}

impl<'env, 'local> JniMixinPhase<'env, 'local> {
    /// `find_class` with the pending `NoClassDefFoundError` cleared.
    fn find(&mut self, name: &str) -> Option<JClass<'local>> {
        let class = self.env.find_class(name).ok();
        if class.is_none() {
            let _ = self.env.exception_clear();
        }
        class
    }

    /// [`PhaseOutcome::Failed`] for a thrown call: the same fallback label the
    /// rest of the probe reports, with the exception cleared.
    fn failed(&mut self, error: jni::errors::Error) -> PhaseOutcome {
        let fallback = (error.to_string() == "Java exception was thrown")
            .then(|| exception_fallback(self.env))
            .flatten();
        let _ = self.env.exception_describe();
        let _ = self.env.exception_clear();
        PhaseOutcome::Failed(fallback.unwrap_or_else(|| error.to_string()))
    }

    /// `class.method(sig)`: `Unavailable` when either is missing, `Failed` when
    /// the call throws.
    fn static_call(
        &mut self,
        class: &str,
        method: &str,
        sig: &str,
        args: &[JValue],
    ) -> Result<JValueOwned<'local>, PhaseOutcome> {
        let Some(class) = self.find(class) else {
            return Err(PhaseOutcome::Unavailable);
        };
        if self.env.get_static_method_id(&class, method, sig).is_err() {
            let _ = self.env.exception_clear();
            return Err(PhaseOutcome::Unavailable);
        }
        match self.env.call_static_method(&class, method, sig, args) {
            Ok(value) => Ok(value),
            Err(error) => Err(self.failed(error)),
        }
    }

    /// `MixinEnvironment$Side.CLIENT` / `.SERVER`.
    fn side_constant(&mut self, side: MixinSide) -> Result<JObject<'local>, PhaseOutcome> {
        let Some(class) = self.find(MIXIN_SIDE_CLASS) else {
            return Err(PhaseOutcome::Unavailable);
        };
        if self
            .env
            .get_static_field_id(&class, side.field(), MIXIN_SIDE_SIG)
            .is_err()
        {
            let _ = self.env.exception_clear();
            return Err(PhaseOutcome::Unavailable);
        }
        match self
            .env
            .get_static_field(&class, side.field(), MIXIN_SIDE_SIG)
        {
            Ok(value) => value.l().map_err(|error| self.failed(error)),
            Err(error) => Err(self.failed(error)),
        }
    }
}

impl MixinPhaseDriver for JniMixinPhase<'_, '_> {
    fn loading_done(&mut self) -> PhaseOutcome {
        self.static_call(MIXIN_BOOTSTRAP_CLASS, MIXIN_ON_LOADING_DONE, "()V", &[])
            .map_or_else(|outcome| outcome, |_| PhaseOutcome::Ok)
    }

    fn set_side(&mut self, side: Option<MixinSide>) -> PhaseOutcome {
        // 1. `MixinEnvironment.getDefaultEnvironment()`.
        let default = match self.static_call(
            MIXIN_ENVIRONMENT_CLASS,
            MIXIN_GET_DEFAULT_ENVIRONMENT,
            MIXIN_GET_DEFAULT_ENVIRONMENT_SIG,
            &[],
        ) {
            Ok(value) => match value.l() {
                Ok(object) => object,
                Err(error) => return self.failed(error),
            },
            Err(outcome) => return outcome,
        };
        // 2. `getDefaultEnvironment().setSide(Side.CLIENT|SERVER)`. `setSide`
        // only assigns while the side is still `UNKNOWN`.
        if let Some(side) = side {
            let constant = match self.side_constant(side) {
                Ok(constant) => constant,
                Err(outcome) => return outcome,
            };
            let Ok(default_class) = self.env.get_object_class(&default) else {
                return PhaseOutcome::Unavailable;
            };
            if self
                .env
                .get_method_id(&default_class, MIXIN_SET_SIDE, MIXIN_SET_SIDE_SIG)
                .is_err()
            {
                let _ = self.env.exception_clear();
                return PhaseOutcome::Unavailable;
            }
            if let Err(error) = self.env.call_method(
                &default,
                MIXIN_SET_SIDE,
                MIXIN_SET_SIDE_SIG,
                &[JValue::Object(&constant)],
            ) {
                return self.failed(error);
            }
        }
        // 3. `MixinEnvironment.setActiveEnvironment(MixinEnvironment)` where the
        // runtime has it. Best effort: the side above is what the game reads.
        let _ = self.static_call(
            MIXIN_ENVIRONMENT_CLASS,
            MIXIN_SET_ACTIVE_ENVIRONMENT,
            MIXIN_SET_ACTIVE_ENVIRONMENT_SIG,
            &[JValue::Object(&default)],
        );
        PhaseOutcome::Ok
    }
}

/// Fabric runs `preLaunch` before the selected environment. NeoForge has no
/// such list, so its `@Mod` scan must not masquerade as one; an explicit
/// `--entry` bypasses discovery and preLaunch with it.
fn pre_launch_entries(
    jar: &Path,
    kind: &str,
    metadata: Option<&str>,
) -> Result<Vec<String>, String> {
    if metadata.is_none() || kind == "neoforge" {
        return Ok(Vec::new());
    }
    discover_entries(jar, "preLaunch")
}

/// NeoForge markers for a jar without Fabric metadata; diagnostics only.
fn neoforge_diagnostic(jar: &Path) -> Option<String> {
    neoforge_metadata(jar).ok()?.diagnostic()
}

fn report_neoforge_metadata(jar: &Path) {
    if let Some(line) = neoforge_diagnostic(jar) {
        eprintln!("horizon-jvm: {line}");
    }
}

/// Every jar under a folder, for `--libs`.
fn jars(dir: &Path) -> Result<(Vec<PathBuf>, usize), String> {
    let mut out = Vec::new();
    let mut skipped_game_jars = 0;
    let mut stack = vec![dir.to_path_buf()];
    while let Some(dir) = stack.pop() {
        let entries = fs::read_dir(&dir).map_err(|e| format!("{}: {e}", dir.display()))?;
        for entry in entries {
            let entry = entry.map_err(|e| format!("{}: {e}", dir.display()))?;
            let path = entry.path();
            if path.is_dir() {
                stack.push(path);
            } else if path.extension().is_some_and(|e| e == "jar") {
                if is_minecraft_runtime_jar(&path) {
                    skipped_game_jars += 1;
                } else {
                    out.push(path);
                }
            }
        }
    }
    out.sort();
    Ok((out, skipped_game_jars))
}

/// A full Minecraft client/server jar must not share `net.minecraft` packages
/// with the unsigned façade: HotSpot rejects that mix with a signer mismatch.
/// Libraries and mods can mention the package in a few descriptors, so use a
/// generous class-count threshold instead of filtering on one class name.
fn is_minecraft_runtime_jar(path: &Path) -> bool {
    let Ok(file) = File::open(path) else {
        return false;
    };
    let Ok(mut archive) = zip::ZipArchive::new(file) else {
        return false;
    };
    let mut game_classes = 0usize;
    for index in 0..archive.len() {
        let Ok(entry) = archive.by_index(index) else {
            continue;
        };
        if is_minecraft_class(entry.name()) {
            game_classes += 1;
            if game_classes >= 32 {
                return true;
            }
        }
    }
    false
}

fn is_minecraft_class(name: &str) -> bool {
    name.starts_with("net/minecraft/") && name.ends_with(".class")
}

/// Extract Fabric's `META-INF/jars/*.jar` entries and add them to the classpath.
fn expand_nested_jars(classpath: &mut Vec<PathBuf>) -> Result<NestedJars, String> {
    const MAX_NESTED_JARS: usize = 4096;
    let extracted = NestedJars::new()?;
    let mut index = 0;
    let mut serial = 0usize;
    while index < classpath.len() {
        let path = classpath[index].clone();
        index += 1;
        let Ok(file) = File::open(&path) else {
            continue;
        };
        let Ok(mut archive) = zip::ZipArchive::new(file) else {
            continue;
        };
        for entry_index in 0..archive.len() {
            let mut entry = archive
                .by_index(entry_index)
                .map_err(|e| format!("{}: reading zip entry: {e}", path.display()))?;
            let Some(name) = nested_jar_name(entry.name()) else {
                continue;
            };
            if serial >= MAX_NESTED_JARS {
                return Err(format!(
                    "nested jar limit exceeded ({MAX_NESTED_JARS}); refusing an unbounded JiJ classpath"
                ));
            }
            let output = extracted.root.join(format!("{serial}-{name}"));
            serial += 1;
            let mut out =
                File::create(&output).map_err(|e| format!("{}: {e}", output.display()))?;
            std::io::copy(&mut entry, &mut out)
                .map_err(|e| format!("{}: {e}", output.display()))?;
            classpath.push(output);
        }
    }
    Ok(extracted)
}

fn nested_jar_name(entry: &str) -> Option<&str> {
    let name = entry.strip_prefix("META-INF/jars/")?;
    if name.is_empty() || name.contains('/') || !name.ends_with(".jar") {
        return None;
    }
    Some(name)
}

